#define HAUT_ECRAN 180.
#define SEGMENT 130.
#define VITESSE 52.
#define HEROS_X0 88.
#define SOL_Y 40.
#define DUREE_SAUT .9
#define HAUT_SAUT 30.
#define HAUT_TUYAU 26.
#define SEG_MAX 4.
#define T_SORTIE 1.0
#define T_DEPART 1.3
#define X_TUYAU ((SEG_MAX + 1.)*SEGMENT + 64.)
#define T_ARRIVEE (T_DEPART + (X_TUYAU - HEROS_X0)/VITESSE)
#define DUREE_NIV (T_ARRIVEE + 1.9)
#define X_STOP 320.
#define X_TETE 400.
#define X_COUP 360.
#define X_PRINC 442.
#define BOSS_X 408.
#define PRINC_X 458.
#define HAUT_TETE 44.
#define CAM_MAX 170.
#define T_BOSS (T_DEPART + (X_STOP - HEROS_X0)/VITESSE)
#define DUREE_BOSS (T_BOSS + 17.5)
#define CYCLE (4.*DUREE_NIV + DUREE_BOSS)

float gNiveau, gDecalage, gHerosX, gBossVivant, gLueur, gSuspendu;
vec3 gFondBas, gFondHaut, gRocheA, gRocheB, gBrique, gMousse, gFosse, gBrume, gCristal0, gCristal1, gCristal2, gAmbiance, gEnnemiA, gEnnemiB, gEnnemiC, gPiqueA, gPiqueB, gPiquePointe;

float hachage11(float p){ p = fract(p*.1031); p *= p+33.33; p *= p+p; return fract(p); }
float hachage21(vec2 p){ vec3 p3 = fract(vec3(p.xyx)*.1031); p3 += dot(p3, p3.yzx+33.33); return fract((p3.x+p3.y)*p3.z); }
vec2  hachage22(vec2 p){ float n = hachage21(p); return vec2(n, hachage21(p+n*17.3)); }

float bruit(vec2 p){
    vec2 i = floor(p), f = fract(p);
    f = f*f*(3.-2.*f);
    return mix(mix(hachage21(i), hachage21(i+vec2(1,0)), f.x),
               mix(hachage21(i+vec2(0,1)), hachage21(i+vec2(1,1)), f.x), f.y);
}
float bruitFbm(vec2 p){
    float a = .5, s = 0.;
    for(int i=0;i<3;i++){ s += a*bruit(p); p = p*2.03+7.1; a *= .5; }
    return s;
}

void definirTheme(float niveau)
{
    gNiveau = niveau;
    gDecalage = niveau*911.;
    gLueur = 1.;
    gSuspendu = 0.;
    if(niveau < .5){
        gFondBas = vec3(.13, .10, .30); gFondHaut = vec3(.02, .015, .06);
        gRocheA = vec3(.06, .045, .15); gRocheB = vec3(.09, .065, .20);
        gBrique = vec3(.20, .16, .32); gMousse = vec3(.10, .42, .36);
        gFosse = vec3(.55, .22, .95); gBrume = vec3(.45, .35, .80);
        gCristal0 = vec3(.2, .9, 1.); gCristal1 = vec3(1., .35, .9); gCristal2 = vec3(.6, .55, 1.);
        gAmbiance = gFondBas*.45; gSuspendu = 1.;
        gEnnemiA = vec3(.45, .90, .40); gEnnemiB = vec3(.40, .75, 1.); gEnnemiC = vec3(1., .55, .85);
        gPiqueA = vec3(.38, .42, .55); gPiqueB = vec3(.80, .84, .95); gPiquePointe = vec3(1.);
    } else if(niveau < 1.5){
        gFondBas = vec3(.34, .09, .04); gFondHaut = vec3(.04, .01, .02);
        gRocheA = vec3(.12, .05, .05); gRocheB = vec3(.17, .07, .06);
        gBrique = vec3(.21, .12, .11); gMousse = vec3(.45, .30, .10);
        gFosse = vec3(1., .45, .12); gBrume = vec3(.90, .35, .20);
        gCristal0 = vec3(1., .50, .15); gCristal1 = vec3(1., .25, .30); gCristal2 = vec3(1., .85, .30);
        gAmbiance = gFondBas*.55; gSuspendu = 1.;
        gEnnemiA = vec3(1., .45, .35); gEnnemiB = vec3(1., .80, .30); gEnnemiC = vec3(.95, .40, .80);
        gPiqueA = vec3(.12, .10, .14); gPiqueB = vec3(.30, .25, .32); gPiquePointe = vec3(1., .55, .15);
    } else if(niveau < 2.5){
        gFondBas = vec3(.10, .20, .40); gFondHaut = vec3(.01, .03, .12);
        gRocheA = vec3(.10, .20, .35); gRocheB = vec3(.18, .32, .50);
        gBrique = vec3(.35, .55, .75); gMousse = vec3(.40, .45, .50);
        gFosse = vec3(.15, .35, .90); gBrume = vec3(.50, .80, 1.);
        gCristal0 = vec3(.5, .95, 1.); gCristal1 = vec3(.80, .75, 1.); gCristal2 = vec3(.95, 1., 1.);
        gAmbiance = gFondBas*.9 + vec3(.06);
        gEnnemiA = vec3(.55, .95, 1.); gEnnemiB = vec3(.95, .97, 1.); gEnnemiC = vec3(.60, .65, 1.);
        gPiqueA = vec3(.45, .75, .95); gPiqueB = vec3(.85, .97, 1.); gPiquePointe = vec3(1.);
        gLueur = .8;
    } else if(niveau < 3.5){
        gFondBas = vec3(.98, .82, .62); gFondHaut = vec3(.35, .62, .95);
        gRocheA = vec3(.45, .72, .55); gRocheB = vec3(.30, .58, .38);
        gBrique = vec3(.45, .30, .20); gMousse = vec3(.30, .55, .18);
        gFosse = vec3(.55, .35, .80); gBrume = vec3(1., .90, .80);
        gCristal0 = vec3(1., .55, .85); gCristal1 = vec3(1., .90, .35); gCristal2 = vec3(.70, .65, 1.);
        gAmbiance = vec3(1., .95, .88);
        gEnnemiA = vec3(1., .60, .45); gEnnemiB = vec3(.95, .85, .35); gEnnemiC = vec3(.75, .55, 1.);
        gPiqueA = vec3(.22, .45, .18); gPiqueB = vec3(.40, .75, .30); gPiquePointe = vec3(1., .75, .85);
        gLueur = .22;
    } else {
        gFondBas = vec3(.20, .12, .30); gFondHaut = vec3(.05, .03, .12);
        gRocheA = vec3(.14, .09, .22); gRocheB = vec3(.22, .14, .32);
        gBrique = vec3(.55, .50, .62); gMousse = vec3(.20, .20, .20);
        gFosse = vec3(.55, .22, .95); gBrume = vec3(.60, .40, .80);
        gCristal0 = vec3(1., .80, .40); gCristal1 = vec3(1., .40, .60); gCristal2 = vec3(.70, .50, 1.);
        gAmbiance = gFondBas*.9 + vec3(.14, .09, .10);
        gEnnemiA = vec3(.45, .90, .40); gEnnemiB = vec3(.40, .75, 1.); gEnnemiC = vec3(1., .55, .85);
        gPiqueA = vec3(.38, .42, .55); gPiqueB = vec3(.80, .84, .95); gPiquePointe = vec3(1.);
    }
}

vec3 cristal(float h)
{
    vec3 c = mix(gCristal0, gCristal1, step(.33, h));
    return mix(c, gCristal2, step(.66, h));
}

vec3 couleurGelee(float h)
{
    vec3 c = mix(gEnnemiA, gEnnemiB, step(.33, h));
    return mix(c, gEnnemiC, step(.66, h));
}

vec3 couleurScarabee(float h)
{
    vec3 c = mix(gEnnemiB, gEnnemiC, step(.33, h));
    return mix(c, gEnnemiA, step(.66, h));
}

vec3 couleurChauveSouris(float h)
{
    return mix(gEnnemiC, gEnnemiB, step(.5, h));
}

vec3 couleurEnnemi(float genre, float h)
{
    return (genre == 4.) ? couleurGelee(h) : ((genre == 5.) ? couleurScarabee(h) : couleurChauveSouris(h));
}

void infoSegment(float idSegment, out float genre, out float xc, out float w)
{
    float sh = idSegment + gNiveau*97.;
    float r = hachage11(sh*7.31 + 1.7);
    float tp = 0.;
    if(idSegment >= 1. && idSegment <= SEG_MAX && gNiveau < 3.5){
        if(r >= .08) tp = 1.;
        if(r >= .26) tp = 2.;
        if(r >= .44) tp = 3.;
        if(r >= .56) tp = 4.;
        if(r >= .72) tp = 5.;
        if(r >= .88) tp = 6.;
    }
    genre = tp;
    xc = floor(idSegment*SEGMENT + 62. + 28.*hachage11(sh*3.9 + 5.));
    w = (tp == 1.) ? 18. : ((tp == 2.) ? 26. : ((tp == 3.) ? 16. : ((tp > 3.5) ? 14. : 0.)));
}

void etatHeros(float tl, out float X, out float y, out float enAir, out float enCourse)
{
    float tArrivee = T_ARRIVEE;
    X = HEROS_X0 + VITESSE*clamp(tl - T_DEPART, 0., tArrivee - T_DEPART);
    enCourse = (tl > T_DEPART && tl < tArrivee) ? 1. : 0.;
    y = 0.;
    enAir = 0.;
    if(tl < T_SORTIE){
        y = HAUT_TUYAU*smoothstep(0., 1., tl/T_SORTIE);
    } else if(tl < T_DEPART){
        y = HAUT_TUYAU;
    } else if(tl < tArrivee - DUREE_SAUT){
        float e = X - HEROS_X0 - 15.;
        if(e < 0.){
            y = HAUT_TUYAU;
        } else {
            float tf = e/VITESSE;
            y = max(0., HAUT_TUYAU - 220.*tf*tf);
            if(y > .5) enAir = 1.;
        }
        float s0 = floor(X/SEGMENT);
        for(int k=-1; k<=1; k++){
            float idSegment = s0 + float(k);
            float genre, xc, w;
            infoSegment(idSegment, genre, xc, w);
            if(genre > 4.5 && genre < 5.5){
                float tj2 = T_DEPART + (xc - 24. - HEROS_X0)/VITESSE;
                float tau1 = (tl - tj2)/(24./VITESSE);
                if(tau1 > 0. && tau1 < 1.){
                    y = max(y, 4.*22.*tau1*(1. - tau1) + 9.*tau1);
                    enAir = 1.;
                }
                float tau2 = (tl - (tj2 + 24./VITESSE))/.5;
                if(tau2 > 0. && tau2 < 1.){
                    y = max(y, 4.*14.*tau2*(1. - tau2) + 9.*(1. - tau2));
                    enAir = 1.;
                }
            }
            if(genre > .5 && genre < 3.5){
                float tj = T_DEPART + (xc - HEROS_X0)/VITESSE - DUREE_SAUT*.5;
                float tau = (tl - tj)/DUREE_SAUT;
                if(tau > 0. && tau < 1.){
                    y = max(y, 4.*HAUT_SAUT*tau*(1. - tau));
                    enAir = 1.;
                }
            }
        }
    } else if(tl < tArrivee){
        float tau = (tl - (tArrivee - DUREE_SAUT))/DUREE_SAUT;
        y = 4.*HAUT_SAUT*tau*(1. - tau) + HAUT_TUYAU*tau;
        enAir = 1.;
    } else if(tl < tArrivee + .5){
        y = HAUT_TUYAU;
    } else {
        y = HAUT_TUYAU - 28.*smoothstep(0., 1., (tl - tArrivee - .5)/.9);
    }
}

void etatEpee(float tl, float X, out float st, out float sp)
{
    st = 0.;
    sp = 0.;
    float s0 = floor(X/SEGMENT);
    for(int k=0; k<2; k++){
        float idSegment = s0 + float(k);
        float genre, xc, w;
        infoSegment(idSegment, genre, xc, w);
        if(genre == 4. || genre == 6.){
            float th = T_DEPART + (xc - 20. - HEROS_X0)/VITESSE;
            float d = tl - th;
            if(d > -.75 && d < .8){
                if(d < -.35){ st = 1.; sp = (d + .75)/.4; }
                else if(d < -.15){ st = 2.; sp = 0.; }
                else if(d < .15){ st = 3.; sp = (d + .15)/.3; }
                else if(d < .45){ st = 4.; sp = (d - .15)/.3; }
                else { st = 5.; sp = (d - .45)/.35; }
            }
        }
    }
}

vec2 posSuspendu(float idSegment, float cameraX)
{
    float sh = idSegment + gNiveau*97.;
    return vec2(idSegment*SEGMENT + 20. + 90.*hachage11(sh*2.3 + 8.) - cameraX, 150. + 8.*hachage11(sh*9.1));
}

vec3 lumiereEn(vec2 P, float cameraX, float hy)
{
    vec3 L = gAmbiance;
    vec2 d0 = P - vec2(gHerosX, SOL_Y + hy + 15.);
    L += vec3(1., .80, .85) * 1.5 * gLueur / (1. + dot(d0, d0)/1800.);
    if(gNiveau > 3.5){
        float cp = floor(cameraX*.6);
        float c0 = floor(cp/110.)*110.;
        for(int i=0; i<5; i++){
            vec2 dt = P - vec2(c0 + float(i)*110. + 55. - cp, SOL_Y + 39.);
            L += vec3(1., .62, .25) * .9 / (1. + dot(dt, dt)/1600.);
        }
        vec2 dp = P - vec2(PRINC_X - cameraX, SOL_Y + 18.);
        L += vec3(1., .60, .80) * .6 / (1. + dot(dp, dp)/2500.);
        vec2 db = P - vec2(BOSS_X - cameraX, SOL_Y + 22.);
        L += vec3(.70, .35, 1.) * .7 * gBossVivant / (1. + dot(db, db)/3000.);
        return L;
    }
    float s0 = floor(cameraX/SEGMENT) - 1.;
    for(int i=0; i<5; i++){
        float idSegment = s0 + float(i);
        float genre, xc, w;
        infoSegment(idSegment, genre, xc, w);
        float hh = hachage11(idSegment*5.5 + 2.);
        if(gSuspendu > .5){
            vec2 dd = P - posSuspendu(idSegment, cameraX);
            L += cristal(hh) * .9 / (1. + dot(dd, dd)/2500.);
        }
        if(genre == 3.){
            vec2 d1 = P - vec2(xc - cameraX, SOL_Y + 8.);
            L += gCristal0 * 1.1 * gLueur / (1. + dot(d1, d1)/900.);
        }
        if(genre > 3.5){
            vec2 d2 = P - vec2(xc - cameraX, SOL_Y + 6.);
            L += couleurEnnemi(genre, hachage11(idSegment*9.7 + 3.)) * .35 * gLueur / (1. + dot(d2, d2)/500.);
        }
    }
    return L;
}

bool bx(vec2 l, float x0, float y0, float x1, float y1)
{
    return l.x >= x0 && l.x <= x1 && l.y >= y0 && l.y <= y1;
}

float distSegment(vec2 p, vec2 a, vec2 b)
{
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba)/dot(ba, ba), 0., 1.);
    return length(pa - ba*h);
}

vec4 pixelHeros(vec2 l, float fr, float enAir, float st, float sp, float clin)
{
    vec4 c = vec4(0.);
    float rebond = (enAir < .5 && (fr == 1. || fr == 3.)) ? 1. : 0.;
    vec2 u = vec2(l.x, l.y - rebond);
    float gardeVisible = (st < .5 || (st < 1.5 && sp < .12) || (st > 4.5 && sp > .88)) ? 1. : 0.;

    if(distSegment(u, vec2(-4., 5.), vec2(-11., 1.)) < .8) c = vec4(.35, .22, .14, 1.);
    if(length(u - vec2(-11., 1.)) < 1.) c = vec4(.90, .70, .30, 1.);
    if(gardeVisible > .5){
        if(bx(u, -4., 6., -4., 7.)) c = vec4(.50, .30, .20, 1.);
        if(bx(u, -5., 5., -3., 5.)) c = vec4(.95, .75, .30, 1.);
        if(bx(u, -4., 8., -4., 8.)) c = vec4(.95, .75, .30, 1.);
    }

    float la = (enAir > .5 || fr == 0.) ? 3. : ((fr == 2.) ? -3. : 0.);
    float lb = -la;
    float jambeY0 = (enAir > .5) ? 1. : 0.;
    vec3 botte = vec3(.42, .26, .16);
    vec3 pantalon  = vec3(.22, .28, .50);
    if(bx(l, lb-1., jambeY0, lb, jambeY0+3.)) c = vec4((l.y - jambeY0 < 2.) ? botte*.8 : pantalon*.8, 1.);
    if(bx(l, la-1., jambeY0, la, jambeY0+3.)) c = vec4((l.y - jambeY0 < 2.) ? botte : pantalon, 1.);

    if(bx(u, -3., 4., 3., 8.)){
        vec3 tn = vec3(.20, .38, .80)*(.85 + .3*step(0., u.x));
        if(abs(u.y - 5.) < .5) tn = vec3(.62, .42, .16);
        if(abs(u.y - 5.) < .5 && abs(u.x) < .5) tn = vec3(.95, .80, .30);
        c = vec4(tn, 1.);
    }

    if(bx(u, -3., 8., 5., 11.)){
        vec3 hd = vec3(.97, .90, .78);
        if(abs(u.y - 8.) < .5) hd = vec3(.82, .72, .60);
        c = vec4(hd, 1.);
    }
    if(clin < .5){
        if(bx(u, 0., 9., 1., 11.) || bx(u, 3., 9., 4., 11.)) c = vec4(.08, .05, .12, 1.);
        if(bx(u, 0., 11., 0., 11.) || bx(u, 3., 11., 3., 11.)) c = vec4(1.);
    } else {
        if(bx(u, 0., 9., 1., 9.) || bx(u, 3., 9., 4., 9.)) c = vec4(.08, .05, .12, 1.);
    }
    if(bx(u, -1., 9., -1., 9.) || bx(u, 5., 9., 5., 9.)) c = vec4(1., .60, .65, 1.);
    if(bx(u, 2., 8., 2., 8.)) c = vec4(.60, .25, .30, 1.);

    if(gardeVisible > .5){
        if(bx(u, 3., 5., 5., 6.)) c = vec4(.70, .50, .30, 1.);
    }

    vec2 cq = (u - vec2(0., 17.))/vec2(8.6, 5.6);
    if(dot(cq, cq) < 1. && u.y >= 12.){
        vec3 cp = mix(vec3(.55, .08, .25), vec3(.95, .30, .45), clamp((u.y - 12.)/10., 0., 1.));
        if(u.y < 13.) cp = vec3(.40, .06, .20);
        vec2 s1 = u - vec2(-4., 19.);
        vec2 s2 = u - vec2(3., 20.);
        vec2 s3 = u - vec2(0., 15.);
        vec2 s4 = u - vec2(6., 16.);
        if(dot(s1,s1) < 3.2 || dot(s2,s2) < 2.6 || dot(s3,s3) < 1.5 || dot(s4,s4) < 1.1) cp = vec3(.99, .95, .85);
        c = vec4(cp, 1.);
    }

    if(gardeVisible < .5){
        float pp = sp;
        vec2 poigne = vec2(5.5, 7.5);
        float angle = radians(35.);
        if(st < 1.5){
            poigne = mix(vec2(-4., 7.), vec2(5.5, 7.5), pp) + vec2(0., 6.*sin(pp*3.14159));
            angle = mix(radians(210.), radians(35.), pp);
        } else if(st < 2.5){
            angle = radians(35.);
        } else if(st < 3.5){
            float a1 = radians(35.);
            float a2 = radians(115.);
            float a3 = radians(-45.);
            angle = (sp < .3) ? mix(a1, a2, sp/.3) : mix(a2, a3, smoothstep(0., 1., (sp - .3)/.7));
        } else if(st < 4.5){
            angle = mix(radians(-45.), radians(35.), smoothstep(0., 1., sp));
        } else {
            pp = 1. - sp;
            poigne = mix(vec2(-4., 7.), vec2(5.5, 7.5), pp) + vec2(0., 6.*sin(pp*3.14159));
            angle = mix(radians(210.), radians(35.), pp);
        }
        vec2 direction = vec2(cos(angle), sin(angle));
        vec2 perpendiculaire = vec2(-direction.y, direction.x);
        if(distSegment(u, vec2(3., 7.), poigne) < .8) c = vec4(.80, .70, .58, 1.);
        if(distSegment(u, poigne - direction*2., poigne) < .6) c = vec4(.45, .28, .18, 1.);
        if(length(u - (poigne - direction*2.5)) < .8) c = vec4(.95, .75, .30, 1.);
        if(distSegment(u, poigne + direction*.8 - perpendiculaire*2.2, poigne + direction*.8 + perpendiculaire*2.2) < .6) c = vec4(.95, .75, .30, 1.);
        float db = distSegment(u, poigne + direction*1.5, poigne + direction*9.5);
        if(db < .75) c = vec4(mix(vec3(.62, .70, .88), vec3(.95, .97, 1.), step(db, .35)), 1.);
        if(length(u - (poigne + direction*9.5)) < 1.) c = vec4(1.);
    }
    return c;
}

vec4 pixelGelee(vec2 l, float k, vec3 corps, float eclair, float clin, float alerte, float tt)
{
    float sx = 7.5*(1. + .15*k);
    float sy = 6.5*(1. - .15*k);
    vec2 q = (l - vec2(0., sy*.55))/vec2(sx, sy*.95);
    vec4 c = vec4(0.);
    float hautPompon = floor(sy*1.52);
    float sw = floor(sin(tt*3.) + .5);
    if(bx(l, sw, hautPompon, sw, hautPompon + 1.)) c = vec4(.30, .70, .30, 1.);
    if(bx(l, 1. + sw, hautPompon + 1., 3. + sw, hautPompon + 1.) || bx(l, 2. + sw, hautPompon + 2., 3. + sw, hautPompon + 2.)) c = vec4(.40, .95, .50, 1.);
    if(dot(q, q) < 1. && l.y >= 0.){
        float g = clamp(l.y/(sy*1.5), 0., 1.);
        vec3 cc = mix(corps*.62, corps*1.18, g);
        if(dot(q, q) > .72 && l.x > 0.) cc = corps*1.05;
        c = vec4(cc, 1.);
        float ey = floor(sy*.62);
        if(clin < .5){
            if(bx(l, -4., ey, -3., ey + 2.) || bx(l, 1., ey, 2., ey + 2.)) c = vec4(.07, .04, .12, 1.);
            if(bx(l, -4., ey + 2., -4., ey + 2.) || bx(l, 1., ey + 2., 1., ey + 2.)) c = vec4(1.);
        } else {
            if(bx(l, -4., ey, -3., ey) || bx(l, 1., ey, 2., ey)) c = vec4(.07, .04, .12, 1.);
        }
        if(alerte > .5){
            if(bx(l, -5., ey + 3., -3., ey + 3.) || bx(l, 1., ey + 3., 3., ey + 3.)) c = vec4(.07, .04, .12, 1.);
        }
        if(bx(l, -1., ey - 2., 0., ey - 2.)) c = vec4(.55, .20, .30, 1.);
        if(bx(l, -6., ey - 1., -5., ey - 1.) || bx(l, 3., ey - 1., 4., ey - 1.)) c = vec4(1., .55, .65, 1.);
        if(bx(l, -5., 8., -4., 8.) || bx(l, -5., 7., -5., 7.)) c = vec4(.97, .98, 1., 1.);
    }
    if(eclair > .5 && c.a > .5) c.rgb = mix(c.rgb, vec3(1.), .85);
    return c;
}

vec4 pixelScarabee(vec2 l, float k, vec3 corps, float eclair, float clin, float tt)
{
    float sx = 7.5*(1. + .15*k);
    float sy = 6.2*(1. - .15*k);
    vec4 c = vec4(0.);
    float ph = floor(tt*8.);
    for(int i=0; i<4; i++){
        float fi = float(i);
        float lx = floor(-5. + fi*3.3 + mod(ph + fi, 2.));
        if(bx(l, lx, 0., lx, 1.)) c = vec4(.12, .08, .16, 1.);
    }
    vec2 q = (l - vec2(0., 1. + sy*.45))/vec2(sx, sy*.9);
    if(dot(q, q) < 1. && l.y >= 1.){
        float g = clamp((l.y - 1.)/(sy*1.35), 0., 1.);
        vec3 cc = mix(corps*.6, corps*1.2, g);
        if(dot(q, q) > .72 && l.x > 0.) cc = corps*1.05;
        c = vec4(cc, 1.);
        if(abs(l.x - 1.) < .6) c = vec4(corps*.45, 1.);
        vec2 d1 = l - vec2(-3., 5.);
        vec2 d2 = l - vec2(4., 4.);
        vec2 d3 = l - vec2(-1., 7.);
        if(dot(d1, d1) < 2.2 || dot(d2, d2) < 2.2 || dot(d3, d3) < 1.4) c = vec4(.99, .95, .85, 1.);
        if(bx(l, -4., 8., -3., 8.)) c = vec4(.97, .98, 1., 1.);
    }
    vec2 hq = (l - vec2(-7., 3.))/vec2(3.4, 3.);
    if(dot(hq, hq) < 1. && l.y >= 1.){
        c = vec4(.95, .88, .78, 1.);
        if(clin < .5){
            if(bx(l, -8., 3., -7., 4.)) c = vec4(.07, .04, .12, 1.);
            if(bx(l, -8., 4., -8., 4.)) c = vec4(1.);
        } else {
            if(bx(l, -8., 3., -7., 3.)) c = vec4(.07, .04, .12, 1.);
        }
        if(bx(l, -6., 2., -6., 2.)) c = vec4(1., .55, .65, 1.);
    }
    if(bx(l, -9., 6., -9., 6.) || bx(l, -10., 7., -10., 7.) || bx(l, -7., 6., -7., 6.) || bx(l, -6., 7., -6., 7.)) c = vec4(.12, .08, .16, 1.);
    if(bx(l, -10., 8., -10., 8.) || bx(l, -6., 8., -6., 8.)) c = vec4(corps*1.2, 1.);
    if(eclair > .5 && c.a > .5) c.rgb = mix(c.rgb, vec3(1.), .85);
    return c;
}

vec4 pixelChauveSouris(vec2 l, vec3 corps, float eclair, float clin, float tt)
{
    vec4 c = vec4(0.);
    float fl = sin(tt*14.);
    vec2 w1 = (l - vec2(-8.5, 1. + 3.*fl))/vec2(4.8, 2.4);
    vec2 w2 = (l - vec2(8.5, 1. + 3.*fl))/vec2(4.8, 2.4);
    if(dot(w1, w1) < 1. || dot(w2, w2) < 1.) c = vec4(corps*.55, 1.);
    if(dot(w1, w1) < .45 || dot(w2, w2) < .45) c = vec4(corps*.8, 1.);
    if(bx(l, -4., 4., -3., 6.) || bx(l, 3., 4., 4., 6.)) c = vec4(corps*.7, 1.);
    vec2 q = l/vec2(5.2, 4.6);
    if(dot(q, q) < 1.){
        c = vec4(mix(corps*.7, corps*1.15, clamp(l.y/9. + .5, 0., 1.)), 1.);
        if(clin < .5){
            if(bx(l, -3., 0., -2., 2.) || bx(l, 1., 0., 2., 2.)) c = vec4(.07, .04, .12, 1.);
            if(bx(l, -3., 2., -3., 2.) || bx(l, 1., 2., 1., 2.)) c = vec4(1.);
        } else {
            if(bx(l, -3., 0., -2., 0.) || bx(l, 1., 0., 2., 0.)) c = vec4(.07, .04, .12, 1.);
        }
        if(bx(l, -1., -2., 0., -2.)) c = vec4(.55, .20, .30, 1.);
        if(bx(l, -1., -3., -1., -3.)) c = vec4(.98, .98, 1., 1.);
        if(bx(l, -4., -1., -4., -1.) || bx(l, 3., -1., 3., -1.)) c = vec4(1., .55, .65, 1.);
    }
    if(eclair > .5 && c.a > .5) c.rgb = mix(c.rgb, vec3(1.), .85);
    return c;
}

vec4 pixelEnnemi(float genre, vec2 l, float k, vec3 bc, float fl, float clin, float al, float tt)
{
    if(genre == 4.) return pixelGelee(l, k, bc, fl, clin, al, tt);
    if(genre == 5.) return pixelScarabee(l, k, bc, fl, clin, tt);
    return pixelChauveSouris(l, bc, fl, clin, tt);
}

vec3 dessinTuyau(vec2 P, float wx, float tuyauX, vec3 couleur, vec3 lumiere, float t)
{
    float dx = wx - tuyauX;
    float yy = P.y - SOL_Y;
    if(yy < 0. || yy >= HAUT_TUYAU) return couleur;
    bool levre = yy >= HAUT_TUYAU - 6.;
    float hw = levre ? 15. : 12.;
    if(abs(dx) >= hw) return couleur;
    float u = dx/hw;
    vec3 pierre = gBrique*1.6 + vec3(.05);
    float sh = 1. - .55*abs(u + .35);
    vec3 pc = pierre*sh;
    if(levre){
        if(yy >= HAUT_TUYAU - 1.) pc = pierre*1.5;
        else if(yy < HAUT_TUYAU - 5.) pc *= .6;
    } else {
        if(mod(yy, 8.) < 1.) pc *= .6;
    }
    if(abs(abs(dx) - hw) < 1.) pc *= .5;
    vec3 resultat = pc*(.4 + .8*lumiere);
    if(levre && yy >= HAUT_TUYAU - 2. && hachage11(floor(dx*.5) + tuyauX) < .5) resultat = gMousse*(.5 + .8*lumiere);
    if(!levre){
        vec2 rq = vec2(abs(dx)/3.5, abs(yy - 11.)/6.);
        float rd = rq.x + rq.y;
        if(rd < 1.5) resultat = gCristal0*.12;
        if(rd < .9) resultat = gCristal0*(1.2 + .4*sin(t*3.));
    }
    return resultat;
}

float masqueCoeur(vec2 hq)
{
    return (bx(hq, -2., 2., -1., 2.) || bx(hq, 1., 2., 2., 2.) || bx(hq, -2., 1., 2., 1.) || bx(hq, -1., 0., 1., 0.) || bx(hq, 0., -1., 0., -1.)) ? 1. : 0.;
}

void etatHerosBoss(float tl, out float X, out float y, out float enAir, out float enCourse)
{
    float T0 = T_BOSS;
    X = HEROS_X0 + VITESSE*clamp(tl - T_DEPART, 0., T0 - T_DEPART);
    enCourse = (tl > T_DEPART && tl < T0) ? 1. : 0.;
    y = 0.;
    enAir = 0.;
    if(tl < T_SORTIE){
        y = HAUT_TUYAU*smoothstep(0., 1., tl/T_SORTIE);
    } else if(tl < T_DEPART){
        y = HAUT_TUYAU;
    } else if(tl < T0){
        float e = X - HEROS_X0 - 15.;
        if(e < 0.){
            y = HAUT_TUYAU;
        } else {
            float tf = e/VITESSE;
            y = max(0., HAUT_TUYAU - 220.*tf*tf);
            if(y > .5) enAir = 1.;
        }
    }
    for(int i=0; i<2; i++){
        float ts = T0 + .8 + 3.6*float(i);
        float tau = (tl - ts)/.9;
        if(tau > 0. && tau < 1.){
            X = X_STOP + (X_TETE - X_STOP)*tau;
            y = 4.*30.*tau*(1. - tau) + HAUT_TETE*tau;
            enAir = 1.;
            enCourse = 0.;
        }
        float tau2 = (tl - ts - .9)/.6;
        if(tau2 > 0. && tau2 < 1.){
            X = X_TETE + (X_STOP - X_TETE)*tau2;
            y = 4.*20.*tau2*(1. - tau2) + HAUT_TETE*(1. - tau2);
            enAir = 1.;
            enCourse = 0.;
        }
    }
    float tj = T0 + .8 + 2.4 + .66 - .45;
    float tauj = (tl - tj)/.9;
    if(tauj > 0. && tauj < 1.){
        y = 4.*HAUT_SAUT*tauj*(1. - tauj);
        enAir = 1.;
    }
    float tF = T0 + 6.;
    float tR = T0 + 8.5;
    if(tl > tF) X = X_STOP + (X_COUP - X_STOP)*clamp((tl - tF)/.9, 0., 1.);
    if(tl > tR) X = X_COUP + (X_PRINC - X_COUP)*clamp((tl - tR)/1.6, 0., 1.);
    if((tl > tF && tl < tF + .9) || (tl > tR && tl < tR + 1.6)) enCourse = 1.;
    float kt = (tl - (T0 + 10.4))/.35;
    if(kt > 0. && kt < 2.){
        y = 3.*abs(sin(kt*3.14159265));
        enAir = 1.;
    }
}

void etatEpeeBoss(float tl, out float st, out float sp)
{
    st = 0.;
    sp = 0.;
    float d = tl - (T_BOSS + 7.4);
    if(d > -.75 && d < .8){
        if(d < -.35){ st = 1.; sp = (d + .75)/.4; }
        else if(d < -.15){ st = 2.; sp = 0.; }
        else if(d < .15){ st = 3.; sp = (d + .15)/.3; }
        else if(d < .45){ st = 4.; sp = (d - .15)/.3; }
        else { st = 5.; sp = (d - .45)/.35; }
    }
}

void etatBoss(float tl, out float by, out float k, out float fl, out float blesse, out float visibilite, out float dd, out float sx)
{
    float T0 = T_BOSS;
    float tS = T0 + .8;
    by = 0.;
    k = .6*sin(tl*3.);
    fl = 0.;
    blesse = 0.;
    visibilite = 1.;
    sx = 0.;
    dd = tl - (T0 + 7.4);
    if(tl > T0 && tl < tS) k = 1.2*sin(tl*40.);
    float tau = (tl - (tS + 1.8))/.6;
    if(tau > 0. && tau < 1.){
        by = 4.*36.*tau*(1. - tau);
        k = -1.5*sin(tau*3.14159265);
    }
    float dl = tl - (tS + 2.4);
    if(dl > 0. && dl < .35) k = 2.*(1. - dl/.35);
    for(int i=0; i<2; i++){
        float dh = tl - (tS + .9 + 3.6*float(i));
        if(dh > 0.) blesse += 1.;
        if(dh > 0. && dh < .45){
            k = 2.*(1. - dh/.45);
            fl = (dh < .1) ? 1. : 0.;
            sx = floor(sin(dh*70.)*1.5 + .5)*(1. - dh/.45);
        }
    }
    if(dd > 0.){
        fl = (dd < .1) ? 1. : 0.;
        k = -1.2*sin(min(dd, .3)*10.);
        visibilite = (dd < .15) ? 1. : ((dd < .6) ? step(.5, mod(floor(dd*30.), 2.)) : 0.);
        sx = floor(sin(dd*70.)*1.5 + .5);
    }
}

vec4 pixelPrincesse(vec2 l, float clin, float bisou)
{
    vec4 c = vec4(0.);
    vec3 cheveux = vec3(.98, .78, .30);
    vec3 peau = vec3(.99, .88, .78);
    if(bx(l, -6., 3., -3., 18.)) c = vec4(cheveux*.85, 1.);
    if(bx(l, -6., 2., -5., 2.) || bx(l, -3., 2., -3., 2.)) c = vec4(cheveux*.7, 1.);
    if(l.y >= 0. && l.y <= 11.){
        float hw = 3. + (11. - l.y)*.55;
        if(abs(l.x - .5) < hw){
            vec3 dc = mix(vec3(.80, .35, .60), vec3(1., .62, .80), clamp(l.y/11., 0., 1.));
            if(mod(floor(l.x + 10.), 3.) < .5 && l.y < 7.) dc *= .88;
            if(l.y >= 8. && l.y < 9.) dc = vec3(.45, .65, 1.);
            if(l.y < 1.5) dc = vec3(1., .95, .97);
            c = vec4(dc, 1.);
        }
    }
    if(bx(l, -3., 9., -3., 10.) || bx(l, 4., 9., 4., 10.)) c = vec4(1., .70, .85, 1.);
    if(bx(l, 2., 7., 3., 8.)) c = vec4(peau, 1.);
    if(bx(l, -3., 12., 4., 19.)) c = vec4(peau, 1.);
    if(bx(l, -3., 18., 4., 20.) || bx(l, -3., 16., -2., 19.) || bx(l, 3., 17., 4., 19.)) c = vec4(cheveux, 1.);
    if(bx(l, -1., 20., 2., 20.)) c = vec4(cheveux*1.15, 1.);
    if(clin < .5 && bisou < .5){
        if(bx(l, 0., 14., 0., 16.) || bx(l, 3., 14., 3., 16.)) c = vec4(.10, .06, .16, 1.);
        if(bx(l, 0., 16., 0., 16.) || bx(l, 3., 16., 3., 16.)) c = vec4(.95, .98, 1., 1.);
        if(bx(l, -1., 16., -1., 16.) || bx(l, 4., 16., 4., 16.)) c = vec4(.10, .06, .16, 1.);
    } else {
        if(bx(l, 0., 15., 1., 15.) || bx(l, 3., 15., 4., 15.)) c = vec4(.10, .06, .16, 1.);
    }
    if(bx(l, -2., 13., -1., 13.) || bx(l, 4., 13., 4., 13.)) c = vec4(1., .60, .70, 1.);
    if(bisou > .5){
        if(bx(l, 2., 12., 2., 12.)) c = vec4(.90, .15, .30, 1.);
    } else {
        if(bx(l, 1., 12., 2., 12.)) c = vec4(.85, .30, .40, 1.);
    }
    if(bx(l, -3., 21., 4., 21.)) c = vec4(.98, .80, .30, 1.);
    if(bx(l, -2., 22., -2., 22.) || bx(l, 0., 22., 1., 23.) || bx(l, 3., 22., 3., 22.)) c = vec4(.98, .80, .30, 1.);
    if(bx(l, 0., 21., 1., 21.)) c = vec4(1., .30, .50, 1.);
    if(bx(l, -5., 16., -3., 18.)) c = vec4(1., .42, .62, 1.);
    if(bx(l, -4., 17., -4., 17.)) c = vec4(.80, .20, .40, 1.);
    return c;
}

vec4 pixelBoss(vec2 l, float k, float blesse, float clin, float eclair)
{
    float sx = 22.*(1. + .15*k);
    float sy = 19.*(1. - .15*k);
    vec3 corps = vec3(.36, .20, .58);
    vec3 creme = vec3(.97, .92, .78);
    vec3 sombre = vec3(.10, .05, .18);
    vec4 c = vec4(0.);
    vec2 f1 = (l - vec2(-9., 1.5))/vec2(6., 3.);
    vec2 f2 = (l - vec2(9., 1.5))/vec2(6., 3.);
    if(dot(f1, f1) < 1. || dot(f2, f2) < 1.) c = vec4(corps*.55, 1.);
    float ay = floor(sy*.8);
    vec2 a1 = (l - vec2(-sx - 1., ay))/vec2(4.5, 3.5);
    vec2 a2 = (l - vec2(sx + 1., ay))/vec2(4.5, 3.5);
    if(dot(a1, a1) < 1. || dot(a2, a2) < 1.) c = vec4(corps*.85, 1.);
    float xGriffe = floor(sx + 4.);
    if(bx(l, -xGriffe - 1., ay + 2., -xGriffe - 1., ay + 3.) || bx(l, xGriffe + 1., ay + 2., xGriffe + 1., ay + 3.)) c = vec4(creme, 1.);
    vec2 q = (l - vec2(0., sy))/vec2(sx, sy);
    if(dot(q, q) < 1. && l.y >= 0.){
        float g = clamp(l.y/(sy*2.), 0., 1.);
        vec3 cc = mix(corps*.6, corps*1.25, g);
        if(dot(q, q) > .8 && l.x > 0.) cc = corps*1.15 + vec3(.04);
        vec2 bq = (l - vec2(0., sy*.42))/vec2(sx*.48, sy*.38);
        if(dot(bq, bq) < 1.) cc = mix(vec3(.55, .40, .75), vec3(.80, .64, .94), clamp(bq.y*.5 + .5, 0., 1.));
        c = vec4(cc, 1.);
        float ey = floor(sy*1.15);
        if(clin < .5){
            if(bx(l, -10., ey, -7., ey + 4.) || bx(l, 7., ey, 10., ey + 4.)) c = vec4(sombre, 1.);
            if(bx(l, -10., ey + 3., -10., ey + 4.) || bx(l, 7., ey + 3., 7., ey + 4.)) c = vec4(1.);
        } else {
            if(bx(l, -10., ey + 1., -7., ey + 1.) || bx(l, 7., ey + 1., 10., ey + 1.)) c = vec4(sombre, 1.);
        }
        if(distSegment(l, vec2(-12., ey + 8.), vec2(-5., ey + 6. - blesse)) < .8 || distSegment(l, vec2(12., ey + 8.), vec2(5., ey + 6. - blesse)) < .8) c = vec4(sombre, 1.);
        float my = ey - 6.;
        if(blesse > .5){
            if(bx(l, -4., my - 2., 4., my)) c = vec4(sombre, 1.);
            if(bx(l, -1., my - 2., 1., my - 2.)) c = vec4(1., .45, .55, 1.);
            if(bx(l, -3., my, -3., my) || bx(l, 3., my, 3., my)) c = vec4(1.);
        } else {
            if(bx(l, -5., my, 5., my) || bx(l, -6., my + 1., -6., my + 1.) || bx(l, 6., my + 1., 6., my + 1.)) c = vec4(sombre, 1.);
            if(bx(l, -3., my - 1., -3., my - 1.) || bx(l, 3., my - 1., 3., my - 1.)) c = vec4(1.);
        }
        if(bx(l, -15., ey - 3., -12., ey - 2.) || bx(l, 12., ey - 3., 15., ey - 2.)) c = vec4(1., .55, .70, 1.);
    }
    float hb = 2.*sy - 5.;
    vec2 hh = vec2(abs(l.x) - 11., l.y - hb);
    if(hh.y >= 0. && hh.y < 9. && abs(hh.x) < 3.4*(1. - hh.y/9.)) c = vec4(creme*(.8 + .25*step(0., l.x)), 1.);
    float cy = floor(2.*sy) - 1.;
    if(bx(l, -6., cy, 6., cy + 2.)) c = vec4(.98, .80, .30, 1.);
    if(bx(l, -6., cy + 2., 6., cy + 2.)) c = vec4(1., .95, .60, 1.);
    if(bx(l, -6., cy + 3., -5., cy + 4.) || bx(l, -1., cy + 3., 1., cy + 5.) || bx(l, 5., cy + 3., 6., cy + 4.)) c = vec4(.98, .80, .30, 1.);
    if(bx(l, 0., cy + 1., 0., cy + 1.)) c = vec4(.95, .15, .30, 1.);
    if(bx(l, -4., cy + 1., -4., cy + 1.) || bx(l, 4., cy + 1., 4., cy + 1.)) c = vec4(.30, .60, 1., 1.);
    if(eclair > .5 && c.a > .5) c.rgb = mix(c.rgb, vec3(1.), .85);
    return c;
}

vec3 couleurSol(float lv, vec2 P, float wx, float hy, vec3 lumiere, float t)
{
    float dy = SOL_Y - P.y;
    vec3 br = vec3(0.);
    vec3 em = vec3(0.);
    if(lv < .5){
        float rangee = floor(dy/8.);
        float decal = 8.*mod(rangee, 2.);
        float briqueX = mod(wx + decal, 16.);
        float briqueY = mod(dy, 8.);
        float idBrique = floor((wx + decal)/16.) + rangee*17. + gDecalage;
        float v = hachage11(idBrique*1.37 + 4.);
        br = gBrique + (v - .5)*.07 + vec3(.04, .03, .06)*hachage11(idBrique*2.9);
        float biseau = 1.;
        if(briqueY < 2.) biseau = 1.35;
        else if(briqueY > 6.) biseau = .72;
        if(briqueX < 2.) biseau *= (P.x < gHerosX) ? .8 : 1.2;
        else if(briqueX > 14.) biseau *= (P.x < gHerosX) ? 1.2 : .8;
        if(briqueX < 1. || briqueY < 1.) biseau = .4;
        br *= biseau;
        if(rangee < 1.){
            br = mix(br, gMousse, .8);
            if(dy < 2.) br = min(gMousse*2.4, vec3(1.));
        }
    } else if(lv < 1.5){
        float rangee = floor(dy/6.);
        float decal = 7.*mod(rangee, 2.);
        float briqueX = mod(wx + decal, 14.);
        float briqueY = mod(dy, 6.);
        float idBrique = floor((wx + decal)/14.) + rangee*23. + gDecalage;
        float v = hachage11(idBrique*1.7 + 2.);
        br = gBrique*(.7 + .6*v);
        if(briqueY < 1. || briqueX < 1.) br *= .45;
        else if(briqueY < 2.) br *= 1.25;
        float n = bruitFbm(vec2(wx, dy)*.05 + gDecalage);
        if(abs(n - .48) < .02) em = gFosse*(1.1 + .3*sin(t*2. + wx*.1));
        em += gFosse*.3*smoothstep(7., 0., dy);
        if(dy < 1.) br = gBrique*.5;
    } else if(lv < 2.5){
        float rangee = floor(dy/8.);
        float decal = 8.*mod(rangee, 2.);
        float briqueX = mod(wx + decal, 16.);
        float briqueY = mod(dy, 8.);
        float idBrique = floor((wx + decal)/16.) + rangee*17. + gDecalage;
        float v = hachage11(idBrique*1.37 + 4.);
        br = gBrique*(.8 + .35*v);
        if(briqueY < 2.) br *= 1.25;
        else if(briqueY > 6.) br *= .75;
        if(briqueX < 1. || briqueY < 1.) br *= .55;
        if(mod(wx*.7 + dy*1.4 + v*40., 37.) < .9) br = mix(br, vec3(.9, .97, 1.), .6);
        float sh = 2. + 2.*bruit(vec2(wx*.2, 1.));
        if(dy < sh) br = vec3(.88, .93, 1.)*(dy < 1. ? 1.05 : .88);
    } else if(lv < 3.5){
        float v = hachage11(floor(wx/3.)*7. + floor(dy/3.)*13. + gDecalage);
        br = gBrique*(.85 + .25*hachage11(floor(wx/6.) + floor(dy/6.)*11.));
        if(v > .9) br = vec3(.62, .58, .52);
        if(mod(dy, 12.) < 1.) br *= .8;
        if(dy < 3.){
            br = min(gMousse*2.4, vec3(1.))*(dy < 1. ? 1.15 : .85);
            if(hachage11(floor(wx/2.) + gDecalage) > .7 && dy < 1.) br = vec3(.45, .85, .3);
        }
    } else {
        float damier = mod(floor(wx/16.) + floor(dy/8.), 2.);
        br = mix(vec3(.82, .76, .82), vec3(.60, .54, .68), damier);
        if(mod(wx, 16.) < 1. || mod(dy, 8.) < 1.) br *= .7;
        if(dy < 6. && wx < PRINC_X + 24.){
            br = vec3(.74, .10, .22)*(.9 + .1*sin(wx*.5));
            if(dy < 1. || dy >= 5.) br = vec3(.98, .80, .30);
            if(mod(wx, 10.) < 2. && dy > 2. && dy < 4.) br = vec3(.98, .80, .30);
        }
    }
    float ombre = exp(-pow((P.x - gHerosX)/7., 2.)) * smoothstep(SOL_Y - 3., SOL_Y, P.y) * (1. - smoothstep(0., 24., hy));
    br *= 1. - .55*ombre;
    return br*lumiere + em;
}

vec3 decor(float lv, vec2 P, float cameraX, vec3 lumiere, float t)
{
    vec3 couleur = mix(gFondBas, gFondHaut, smoothstep(0., HAUT_ECRAN, P.y));
    if(lv < .5){
    float brumeN = bruitFbm(vec2(P.x + floor(cameraX*.1) + gDecalage, P.y)*vec2(.012, .02));
    couleur += gBrume * brumeN * .12;

    {
        float x = P.x + floor(cameraX*.25) + gDecalage;
        float cellule = 46.;
        float id = floor(x/cellule);
        float f = fract(x/cellule);
        float longueur = 26. + 40.*hachage11(id*1.7 + 3.);
        float e = (HAUT_ECRAN - P.y) - (10. + longueur*(1. - abs(f - .5)*2.));
        if(e < 0.) couleur = mix(gRocheA*2.4, gRocheA, step(2., -e));
    }

    {
        float x = P.x + floor(cameraX*.45) + gDecalage;
        float cellule = 160.;
        float id = floor(x/cellule);
        if(hachage11(id*3.3 + 2.) > .45){
            float px = floor((id + .3 + .4*hachage11(id*1.9))*cellule);
            float dx = x - px;
            float sommet = 108. + 40.*hachage11(id*5.7);
            bool casse = hachage11(id*7.1) < .4;
            if(casse) sommet -= 6.*hachage11(floor(dx*.5) + id*13.);
            if(abs(dx) < 6. && P.y < sommet){
                vec3 pc = gRocheB*1.5;
                if(mod(floor(dx + 6.), 3.) < .5) pc *= .72;
                couleur = pc*(.35 + .7*lumiere);
            }
            if(!casse && abs(dx) < 9. && P.y < sommet + 4. && P.y >= sommet) couleur = gRocheB*2.*(.35 + .7*lumiere);
            if(abs(dx) < 8. && P.y < SOL_Y + 8.) couleur = gRocheB*2.*(.35 + .7*lumiere);
        }
    }

    {
        float x = P.x + floor(cameraX*.5) + gDecalage;
        float cellule = 34.;
        float id = floor(x/cellule);
        float f = fract(x/cellule);
        float longueur = 18. + 32.*hachage11(id*2.1 + 7.);
        float e = (HAUT_ECRAN - P.y) - (8. + longueur*(1. - abs(f - .5)*2.));
        if(e < 0.){
            vec3 couleurEtoile3 = mix(gRocheB*2.6, gRocheB, step(2., -e));
            couleur = couleurEtoile3*(.45 + .7*lumiere);
        }
    }

    {
        float x = P.x + floor(cameraX*.65) + gDecalage;
        float cellule = 75.;
        float id = floor(x/cellule);
        float hh = hachage11(id*4.1 + 9.);
        float cx = (id + .3 + .4*hachage11(id*1.3))*cellule;
        vec3 cc = cristal(hh);
        for(int k=0; k<3; k++){
            float fk = float(k);
            float sx = cx + (fk - 1.)*9. + 3.*hachage11(id + fk);
            float hauteur = 14. + 20.*hachage11(id*3.3 + fk*7.) - fk*2.;
            float wd = 4. + 3.*hachage11(id*5.1 + fk);
            float dx = x - sx;
            float dy = P.y - (SOL_Y - 6.);
            float diamant = abs(dx)/wd + abs(dy - hauteur)/hauteur;
            if(diamant < 1.) couleur = cc*(.55 + .5*step(0., dx));
            else couleur += cc * .22 * exp(-(diamant - 1.)*2.5);
        }
    }

    {
        float u = P.x + floor(cameraX*.3) + P.y*.5;
        float s = sin(u*.05 + 1.3)*.5 + sin(u*.021)*.5;
        couleur += mix(gBrume, vec3(.6, .7, 1.), .5) * smoothstep(.55, 1., s) * smoothstep(40., HAUT_ECRAN, P.y) * .10;
    }
    } else if(lv < 1.5){
        float sm = bruitFbm(vec2(P.x + floor(cameraX*.08) + gDecalage, P.y)*vec2(.01, .03) + t*.02);
        couleur += gBrume*sm*smoothstep(60., HAUT_ECRAN, P.y)*.22;
        {
            float x = P.x + floor(cameraX*.15) + gDecalage;
            float cellule = 240.;
            float id = floor(x/cellule);
            float dx = x - (id + .5)*cellule;
            float sommet = 95. + 45.*hachage11(id*3.1 + 2.);
            float yT = sommet - max(abs(dx), 7.)*.8;
            if(P.y < yT){
                float n = bruit(vec2(x, P.y)*.08);
                couleur = gRocheA*(1.4 + n);
                if(abs(dx - 5.*sin(P.y*.15 + id)) < 1.1 && P.y > SOL_Y && P.y > yT - 55.) couleur = gCristal0*(1.3 + .4*sin(t*2. + P.y*.2));
                if(yT - P.y < 3.) couleur = gRocheB*2.;
            }
            couleur += gCristal0*.5*exp(-length(vec2(dx*.6, P.y - yT))*.09);
        }
        {
            float x = P.x + floor(cameraX*.45) + gDecalage;
            float cellule = 15.;
            float id = floor(x/cellule);
            float f = x - id*cellule;
            float ht = SOL_Y + 14. + 70.*pow(bruit(vec2(id*.12, 5.)), 2.) + 8.*hachage11(id*1.9);
            if(P.y < ht){
                vec3 bc = gRocheB*1.5;
                if(f < 1.) bc *= .5;
                if(ht - P.y < 2.) bc = gRocheB*2.4;
                couleur = bc*(.4 + .7*lumiere);
            }
            couleur += gCristal0*.22*smoothstep(SOL_Y + 16., SOL_Y, P.y);
        }
    } else if(lv < 2.5){
        {
            vec2 decal = vec2(floor(cameraX*.02), 0.);
            vec2 c = floor((P + decal)/5.);
            vec2 pp = floor(hachage22(c + 7.)*5.);
            vec2 lc = floor(P + decal) - c*5.;
            if(hachage21(c) > .94 && lc.x == pp.x && lc.y == pp.y && P.y > 70.)
                couleur += vec3(.8, .9, 1.)*(.55 + .45*sin(t*2. + hachage21(c + 3.)*60.));
        }
        {
            float xa = P.x + floor(cameraX*.05);
            float ruban = 118. + 14.*sin(xa*.02 + t*.15) + 6.*sin(xa*.047 - t*.1);
            float yy = (P.y - ruban)/18.;
            float n = bruit(vec2(xa*.07, t*.12));
            float bande = exp(-yy*yy)*(.3 + .7*n)*smoothstep(60., 100., P.y);
            vec3 ac = mix(vec3(.2, 1., .6), vec3(.65, .4, 1.), clamp((P.y - 105.)/50., 0., 1.));
            couleur += ac*bande*.45;
        }
        {
            vec2 mc = P - vec2(238., 140.);
            if(length(mc) < 13. && length(mc - vec2(5., 3.)) > 11.) couleur = vec3(.96, .97, 1.);
        }
        {
            float x = P.x + floor(cameraX*.2) + gDecalage;
            float cellule = 130.;
            float id = floor(x/cellule);
            float dx = x - (id + .5)*cellule;
            float sommet = 70. + 50.*hachage11(id*3.7 + 1.);
            float yT = sommet - abs(dx)*1.15 + 4.*hachage11(floor(x*.4));
            if(P.y < yT){
                couleur = gRocheB*(1.5 + .7*step(0., -dx));
                if(yT - P.y < 9. + 5.*hachage11(floor(x*.3) + id)) couleur = vec3(.80, .90, 1.)*(.75 + .3*step(0., -dx));
            }
        }
        {
            float x = P.x + floor(cameraX*.55) + gDecalage;
            float cellule = 32.;
            float id = floor(x/cellule);
            if(hachage11(id*2.9 + 5.) > .3){
                float cx = (id + .2 + .6*hachage11(id*1.3))*cellule;
                float dx = x - cx;
                float ht = 38. + 30.*hachage11(id*4.7);
                float tt = (P.y - (SOL_Y + 4.))/ht;
                if(tt > 0. && tt < 1.){
                    float frac2 = fract(tt*4.);
                    float hw = 12.*(1. - tt)*(.55 + .45*frac2);
                    if(abs(dx) < hw){
                        vec3 pc = gRocheA*.7 + vec3(0., .05, .04);
                        if(frac2 > .78) pc = vec3(.85, .92, 1.);
                        couleur = pc*(.55 + .6*lumiere);
                    }
                }
                if(abs(dx) < 1.5 && P.y > SOL_Y - 2. && P.y <= SOL_Y + 6.) couleur = vec3(.25, .17, .14)*(.5 + .6*lumiere);
            }
        }
    } else if(lv < 3.5){
        {
            vec2 couleurEtoile = P - vec2(246., 136.);
            if(length(couleurEtoile) < 14.) couleur = vec3(1., .96, .78);
        }
        {
            float cn = bruitFbm(vec2((P.x + floor(cameraX*.06))*.014 + t*.01, P.y*.045));
            float cm = smoothstep(.56, .64, cn)*smoothstep(78., 108., P.y);
            couleur = mix(couleur, vec3(1., .97, .95), cm*.85);
        }
        for(int k=0; k<3; k++){
            float fk = float(k);
            float x = P.x + floor(cameraX*(.12 + .17*fk)) + gDecalage + fk*50.;
            float hh = SOL_Y + 42. - fk*9. + 16.*sin(x*(.012 + .006*fk) + fk*2.) + 7.*sin(x*.037 + fk);
            if(P.y < hh){
                vec3 hc = mix(gRocheA, gRocheB, fk*.5);
                hc = mix(hc, gFondBas, .35*(1. - fk*.5));
                hc *= 1. + .18*smoothstep(4., 0., hh - P.y);
                couleur = hc;
            }
        }
        {
            float x = P.x + floor(cameraX*.62) + gDecalage;
            float cellule = 66.;
            float id = floor(x/cellule);
            if(hachage11(id*2.3 + 1.) > .3){
                float cx = (id + .25 + .5*hachage11(id*1.7))*cellule;
                float dx = x - cx;
                float ht = 34. + 18.*hachage11(id*4.1);
                if(abs(dx) < 2.5 && P.y > SOL_Y - 3. && P.y < SOL_Y + ht*.55) couleur = vec3(.38, .24, .16)*(.7 + .4*step(0., -dx))*(.6 + .4*lumiere);
                vec2 q = vec2(dx, P.y - (SOL_Y + ht*.8))/vec2(16., 13.);
                if(dot(q, q) < 1.){
                    vec3 lc = mix(gRocheB*.85, gRocheB*1.5, clamp(.5 + q.y*.5 - q.x*.2, 0., 1.));
                    if(hachage11(floor(x*.5) + floor(P.y*.5)*17. + id) > .93) lc = vec3(1., .72, .82);
                    couleur = lc*(.75 + .3*lumiere);
                }
            }
        }
    } else {
        {
            float wy = floor(P.y/9.);
            float xMondeDec = P.x + floor(cameraX*.3) + gDecalage + 9.*mod(wy, 2.);
            if(mod(P.y, 9.) < 1. || mod(xMondeDec, 18.) < 1.) couleur *= .82;
        }
        {
            float x = P.x + floor(cameraX*.3) + gDecalage;
            float cellule = 96.;
            float id = floor(x/cellule);
            float dx = x - (id + .5)*cellule;
            float ay = P.y - 100.;
            if(abs(dx) < 11. && P.y > 60. && (P.y < 100. || dx*dx + ay*ay < 121.)){
                float gi = floor((dx + 11.)/5.5) + floor(P.y/12.);
                float h = hachage11(gi*3.7 + id);
                vec3 gg = mix(vec3(.90, .25, .40), vec3(.30, .50, 1.), step(.4, h));
                gg = mix(gg, vec3(1., .85, .40), step(.8, h));
                couleur = gg*.6;
                if(abs(dx) > 9.5 || P.y < 62. || mod(dx + 11., 5.5) < .8 || mod(P.y, 12.) < .8) couleur = vec3(.75, .60, .25)*.6;
            }
        }
        {
            float u = P.x + floor(cameraX*.3) + P.y*.6;
            couleur += vec3(.5, .55, .9)*smoothstep(.6, 1., sin(u*.04))*smoothstep(40., HAUT_ECRAN, P.y)*.06;
        }
        {
            float x = P.x + floor(cameraX*.6);
            float cellule = 110.;
            float id = floor(x/cellule);
            float dx = x - (id + .5)*cellule;
            if(abs(dx) < 9.){
                vec3 pc = gRocheB*1.9*(.85 + .15*cos(dx*.8));
                if(mod(floor(dx + 9.), 4.) < 1.) pc *= .8;
                couleur = pc*(.4 + .7*lumiere);
            }
            if(abs(dx) < 11. && (P.y > 152. || P.y < SOL_Y + 8.)) couleur = gRocheB*2.3*(.4 + .7*lumiere);
            if(abs(dx) < 5. && P.y > 100. + abs(dx)*1.2 && P.y < 140.){
                vec3 bc = vec3(.75, .10, .25);
                if(P.y > 138.) bc = vec3(.98, .80, .30);
                vec2 hq = vec2(floor(dx), floor(P.y - 123.));
                if(masqueCoeur(hq) > .5) bc = vec3(.98, .80, .30);
                couleur = bc*(.5 + .6*lumiere);
            }
            if(abs(dx) < 1. && abs(P.y - (SOL_Y + 30.)) < 3.) couleur = vec3(.20, .16, .14);
            vec2 fq = vec2(dx + sin(t*12. + id)*.35, P.y - (SOL_Y + 39.))/vec2(2.4, 4.5);
            float fd = length(fq);
            if(fd < 1.) couleur = mix(vec3(1.), vec3(1., .40, .10), clamp(fd*1.3, 0., 1.))*1.4;
        }
    }
    return couleur;
}


void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    float sc = iResolution.y/HAUT_ECRAN;
    vec2 P = floor(fragCoord/sc) + .5;
    float t = iTime;
    float cycle = mod(t, CYCLE);
    float niveau = (cycle < 4.*DUREE_NIV) ? floor(cycle/DUREE_NIV) : 4.;
    float tl = cycle - niveau*DUREE_NIV;
    float niveauBoss = (niveau > 3.5) ? 1. : 0.;
    definirTheme(niveau);

    float Xh, hautHerosBrut, enAir, enCourse;
    if(niveauBoss > .5) etatHerosBoss(tl, Xh, hautHerosBrut, enAir, enCourse);
    else etatHeros(tl, Xh, hautHerosBrut, enAir, enCourse);
    float hy = floor(hautHerosBrut + .5);
    float cameraX = (niveauBoss > .5) ? clamp(floor(Xh) - HEROS_X0, 0., CAM_MAX) : floor(Xh - HEROS_X0);
    gHerosX = floor(Xh) - cameraX;

    float st, sp;
    if(niveauBoss > .5) etatEpeeBoss(tl, st, sp);
    else etatEpee(tl, Xh, st, sp);
    if(st > 3.5 && st < 4.5){
        float saut = floor(3.*sin(sp*3.14159) + .5);
        hy += saut;
        if(saut > .5) enAir = 1.;
    }
    if(st > 2.5 && st < 3.5 && sp > .5 && sp < .75) P.x += mod(floor(t*60.), 2.)*2. - 1.;

    float tSaut0 = T_BOSS + .8;
    float tK = T_BOSS + 10.4;
    float bY = 0., bK = 0., bEclair = 0., bBlesse = 0., bVisible = 0., bMortDt = -9., bSecousse = 0.;
    gBossVivant = 0.;
    if(niveauBoss > .5){
        etatBoss(tl, bY, bK, bEclair, bBlesse, bVisible, bMortDt, bSecousse);
        gBossVivant = bVisible;
        if((tl > tSaut0 + 2.4 && tl < tSaut0 + 2.55) || (tl > tSaut0 + .9 && tl < tSaut0 + 1.0) || (tl > tSaut0 + 4.5 && tl < tSaut0 + 4.6) || (tl > T_BOSS + 7.4 && tl < T_BOSS + 7.7))
            P.x += mod(floor(t*60.), 2.)*2. - 1.;
    }

    float fr = (enCourse > .5) ? floor(mod(cycle*10., 4.)) : 5.;
    float clin = step(.96, fract(t*.33));
    float bisouActif = (niveauBoss > .5 && tl > tK - .05 && tl < tK + 1.4) ? 1. : 0.;
    float clinHeros = max(clin, bisouActif);

    vec3 lumiere = lumiereEn(P, cameraX, hy);
    float wx = P.x + cameraX;

    vec3 couleur = decor(niveau, P, cameraX, lumiere, t);

    float idSegmentCourant = floor(wx/SEGMENT);
    float genre, xc, w;
    infoSegment(idSegmentCourant, genre, xc, w);
    float dansFosse = (genre == 2. && abs(wx - xc) < w*.5) ? 1. : 0.;

    if(P.y < SOL_Y){
        if(dansFosse > .5){
            float g = exp(-P.y/22.);
            float n = bruitFbm(vec2(wx*.05, P.y*.08 - t*.8));
            couleur = gFondHaut*.4 + gFosse*g*.55*(.6 + .8*n);
            float ed = abs(abs(wx - xc) - w*.5);
            if(ed < 1.5) couleur = gBrique*.7*(.4 + lumiere*.9);
        } else {
            couleur = couleurSol(niveau, P, wx, hy, lumiere, t);
        }
    } else {
        float yy = P.y - SOL_Y;
        if(dansFosse < .5 && yy < 7. && gNiveau < 3.5){
            float gx = wx + gDecalage + floor(sin(t*2. + wx*.15)*yy*.3 + .5);
            float idHerbe = floor(gx*.5);
            float hb = 1.5 + 5.*hachage11(idHerbe*3.1 + 1.);
            if(hachage11(idHerbe*1.7 + 9.) < .45 && yy < hb && !(yy > hb - 1.5 && mod(floor(gx), 2.) > .5))
                couleur = mix(gMousse*.5, min(gMousse*2.4, vec3(1.)), yy/hb)*(.4 + .8*lumiere);
        }
        if(dansFosse < .5 && gNiveau < 3.5){
            float xMondeDec = wx + gDecalage;
            float milieu = floor(xMondeDec/70.);
            if(hachage11(milieu*2.7 + 4.) < .6){
                float xChampi = floor((milieu + .2 + .6*hachage11(milieu*5.3 + 1.))*70.);
                float t2, x2, w2;
                infoSegment(floor((xChampi - gDecalage)/SEGMENT), t2, x2, w2);
                if(t2 == 0.){
                    float cr = 2.5 + 2.*hachage11(milieu*1.9);
                    float hauteurTige = 3. + 3.*hachage11(milieu*8.1);
                    vec2 q = vec2(xMondeDec - xChampi, yy);
                    vec3 gc = (hachage11(milieu*6.6) < .5) ? gCristal0 : gCristal1;
                    if(abs(q.x) < 1. && q.y < hauteurTige) couleur = vec3(.85, .85, .95)*(.4 + .6*lumiere)*.8;
                    vec2 cq = (q - vec2(0., hauteurTige))/vec2(cr, cr*.6);
                    if(dot(cq, cq) < 1. && q.y >= hauteurTige - .5) couleur = gc*(.7 + .5*step(0., cq.y));
                    couleur += gc*.2*exp(-length(q - vec2(0., hauteurTige))/6.);
                }
            }
        }
        if(genre == 1. && abs(wx - xc) < w*.5){
            float u = (wx - (xc - w*.5))/6.;
            float hs = 11.*(1. - abs(fract(u) - .5)*2.);
            if(yy < hs){
                vec3 couleurPique = mix(gPiqueA, gPiqueB, step(.5, fract(u)));
                if(yy > hs - 2.) couleurPique = gPiquePointe;
                couleur = couleurPique*(.35 + .8*lumiere);
            }
        }
        if(genre == 3.){
            vec2 q = vec2(wx - xc, yy);
            float d1 = abs(q.x + 3.)/5. + abs(q.y - 8.)/8.;
            float d2 = abs(q.x - 4.)/4. + abs(q.y - 6.)/6.;
            vec3 cc = gCristal0;
            float dm = min(d1, d2);
            if(d2 < 1.) couleur = cc*(.50 + .50*step(0., q.x - 4.));
            if(d1 < 1.) couleur = cc*(.65 + .55*step(0., q.x + 3.));
            if(dm >= 1.) couleur += cc * .3 * exp(-(dm - 1.)*2.5);
        }
    }

    if(niveauBoss > .5){
        float tw = tl - (tSaut0 + 2.4);
        if(tw > 0. && tw < 1.8){
            float dq = wx - (BOSS_X - 24. - 100.*tw);
            float yy = P.y - SOL_Y;
            float hauteur = 9.*(1. - abs(dq)/6.);
            if(abs(dq) < 6. && yy >= 0. && yy < hauteur) couleur = mix(vec3(1., .60, .90), vec3(1., .95, .60), yy/hauteur)*1.2;
        }
    }

    if(genre > 3.5){
        float ph = hachage11(idSegmentCourant*4.4)*6.28;
        float s = sin(t*3. + ph);
        float th = (genre == 5.) ? T_DEPART + (xc - HEROS_X0)/VITESSE : T_DEPART + (xc - 20. - HEROS_X0)/VITESSE;
        float dt = tl - th;
        float xMonde = (genre == 5.) ? xc + 14.*clamp(th - tl, 0., 1.2) : xc;
        float ennemiX = floor(xMonde - cameraX);
        float tMort = (genre == 5.) ? .35 : .15;
        float alerte = smoothstep(95., 75., xc - Xh);
        vec3 bc = couleurEnnemi(genre, hachage11(idSegmentCourant*9.7 + 3.));
        float fl = (dt > 0. && dt < .08) ? 1. : 0.;
        float al = (alerte > .5 && dt < 0.) ? 1. : 0.;
        float kk = (dt < 0.) ? ((genre == 4.) ? -.5*s : 0.) : min(5.5, 1. + 30.*dt);
        float yh = (genre == 4. && dt < 0.) ? floor(max(s, 0.)*4. + .5) : 0.;
        float yCentre = (genre == 6.) ? floor(SOL_Y + 15. + floor(sin(t*3. + ph)*2. + .5)) : SOL_Y + 5.;
        float balancement = (genre == 6.) ? floor(sin(t*2. + ph)*2. + .5) : 0.;
        vec2 le;
        if(genre == 6.) le = vec2(floor(P.x) - ennemiX - balancement, floor(P.y) - yCentre);
        else le = vec2(floor(P.x) - ennemiX, floor(P.y) - (SOL_Y + yh));
        if(dt < tMort && abs(le.x) < 18. && le.y > -13. && le.y < 24.){
            vec4 sl = pixelEnnemi(genre, le, kk, bc, fl, clin, al, t);
            if(sl.a > .5){
                couleur = sl.rgb*clamp(.5 + .65*lumiere, 0., 1.5) + bc*.12;
            } else {
                float nb = pixelEnnemi(genre, le + vec2(1., 0.), kk, bc, fl, clin, al, t).a
                         + pixelEnnemi(genre, le - vec2(1., 0.), kk, bc, fl, clin, al, t).a
                         + pixelEnnemi(genre, le + vec2(0., 1.), kk, bc, fl, clin, al, t).a
                         + pixelEnnemi(genre, le - vec2(0., 1.), kk, bc, fl, clin, al, t).a;
                if(nb > .5) couleur = vec3(.04, .06, .10);
            }
        }
        if(dt < 0. && alerte > .5){
            float marqueY = (genre == 6.) ? yCentre - SOL_Y - 3. : yh;
            vec2 lm = vec2(floor(P.x) - ennemiX, floor(P.y) - (SOL_Y + marqueY + floor(abs(sin(t*8.))*2.)));
            if(bx(lm, -2., 14., 1., 23.)) couleur = vec3(.10, .05, .15);
            if(bx(lm, -1., 18., 0., 22.) || bx(lm, -1., 15., 0., 16.)) couleur = vec3(1., .90, .30);
        }
        if(dt >= 0. && dt < 1.3){
            vec2 ec = vec2(ennemiX, (genre == 6.) ? yCentre : SOL_Y + 5.);
            float vie = max(dt - (tMort - .05), 0.);
            float fondu = clamp(1. - vie, 0., 1.);
            vec2 fp = floor(P);
            if(dt < .06){
                vec2 dq = fp - floor(ec);
                if((abs(dq.x) < 1. && abs(dq.y) < 8.) || (abs(dq.y) < 1. && abs(dq.x) < 8.) || length(dq) < 6.) couleur += vec3(1.);
            }
            for(int i=0; i<8; i++){
                float fi = float(i);
                float angle = fi*.785 + hachage11(idSegmentCourant + fi)*.4;
                vec2 position = ec + vec2(cos(angle), sin(angle))*34.*vie + vec2(0., 10.*vie - 28.*vie*vie);
                vec2 dq = fp - floor(position);
                float etoile = (abs(dq.x) + abs(dq.y) <= 1.) ? 1. : 0.;
                vec3 couleurEtoile = (mod(fi, 2.) < .5) ? bc*1.5 : vec3(1., .95, .7);
                couleur += couleurEtoile*etoile*fondu*(.6 + .4*sin(t*20. + fi));
            }
            vec2 hp = ec + vec2(sin(vie*8.)*2., 6. + 24.*vie);
            couleur += vec3(1., .45, .65)*masqueCoeur(fp - floor(hp))*clamp(1.5 - vie*1.2, 0., 1.);
        }
    }

    if(gSuspendu > .5){
        float s0 = floor(cameraX/SEGMENT) - 1.;
        for(int i=0; i<5; i++){
            float idSegmentSusp = s0 + float(i);
            float hh = hachage11(idSegmentSusp*5.5 + 2.);
            vec2 dd = P - posSuspendu(idSegmentSusp, cameraX);
            vec3 cc = cristal(hh);
            if(niveau < .5){
                float diamant = abs(dd.x)/5. + abs(dd.y)/16.;
                if(diamant < 1.) couleur = cc*(.65 + .5*step(0., dd.x));
                else couleur += cc*.18*exp(-(diamant - 1.)*2.2);
                couleur += cc*.10/(1. + dot(dd, dd)/400.);
            } else {
                if(abs(dd.x) < .5 && dd.y > 0.) couleur = vec3(.12, .08, .08);
                float lq = abs(dd.x)/4.5 + abs(dd.y + 1.)/7.;
                if(lq < 1.) couleur = cc*(.6 + .6*step(0., dd.x));
                if(lq < .4) couleur = vec3(1., .95, .70)*1.3;
                couleur += cc*.08/(1. + dot(dd, dd)/400.);
            }
        }
    }

    float brumeSol = bruitFbm(vec2(wx*.02 + t*.05, P.y*.05));
    couleur += gBrume * brumeSol * smoothstep(SOL_Y + 40., SOL_Y - 5., P.y) * .10;

    if(niveau < 1.5){
        float x = P.x + floor(cameraX*1.15) + gDecalage;
        float cellule = 58.;
        float id = floor(x/cellule);
        float f = fract(x/cellule);
        float longueur = 14. + 22.*hachage11(id*2.9 + 1.);
        float e = (HAUT_ECRAN - P.y) - (6. + longueur*(1. - abs(f - .5)*2.));
        if(e < 0.) couleur = gFondHaut*1.6*(.6 + .6*lumiere) + gRocheA*.8*step(-1.5, e);
    }

    if(enCourse > .5 && P.y < SOL_Y + 14. && P.x < gHerosX){
        for(int i=0; i<6; i++){
            float vie = mod(tl - float(i)*.1, .6);
            vec2 pp = vec2(gHerosX - 4. - VITESSE*vie, SOL_Y + 2. + vie*9.);
            float r = 2.2*(1. - vie/.6);
            float d = length(P - floor(pp) - .5);
            if(d < r && enAir < .5) couleur = mix(couleur, vec3(.75, .70, .85)*(.4 + .6*lumiere), .6*(1. - vie/.6));
        }
    }

    if(niveauBoss > .5 && bVisible > .5){
        float bossX = floor(BOSS_X - cameraX + bSecousse);
        vec2 le = vec2(floor(P.x) - bossX, floor(P.y) - (SOL_Y + floor(bY + .5)));
        if(abs(le.x) < 34. && le.y > -4. && le.y < 60.){
            vec4 bl = pixelBoss(le, bK, bBlesse, clin, bEclair);
            if(bl.a > .5){
                couleur = bl.rgb*clamp(.5 + .65*lumiere, 0., 1.5);
            }
        }
    }

    vec2 centre = vec2(floor((gHerosX + PRINC_X - cameraX)*.5), SOL_Y + 22.);
    if(niveauBoss > .5){
        float princX = floor(PRINC_X - cameraX);
        float kp = (tl - tK)/.35;
        float sautPrincesse = (kp > 0. && kp < 2.) ? floor(3.*abs(sin(kp*3.14159265)) + .5) : floor(.5 + .5*sin(t*3.));
        vec2 lp = vec2(-(floor(P.x) - princX), floor(P.y) - (SOL_Y + sautPrincesse));
        if(abs(lp.x) < 12. && lp.y > -2. && lp.y < 26.){
            vec4 pc = pixelPrincesse(lp, clin, bisouActif);
            if(pc.a > .5){
                couleur = pc.rgb*clamp(.55 + .6*lumiere, 0., 1.6);
            }
        }
        if(bMortDt < .15){
            float dxCage = P.x - princX;
            float yc = P.y - SOL_Y;
            float gl = .8 + .25*sin(t*4.);
            if(abs(dxCage) < 10. && yc >= 0. && yc < 31.){
                float barreau = (mod(dxCage + 10., 4.) < 1.) ? 1. : 0.;
                float bord = (yc < 1. || yc >= 29.) ? 1. : 0.;
                if(barreau > .5 || bord > .5) couleur = vec3(1., .85, .40)*gl*1.2;
                else couleur += vec3(1., .60, .80)*.05;
            }
        }
        if(bMortDt > .15 && bMortDt < 1.4){
            float vie = bMortDt - .15;
            vec2 fp = floor(P);
            vec2 centrePrinc = vec2(princX, SOL_Y + 14.);
            for(int i=0; i<6; i++){
                float fi = float(i);
                float angle = fi*1.047 + hachage11(fi*1.7)*.3;
                vec2 position = centrePrinc + vec2(cos(angle), sin(angle))*(18. + 14.*hachage11(fi))*vie*1.6 + vec2(0., 6.*vie - 10.*vie*vie);
                vec2 dq = fp - floor(position);
                float etoile = (abs(dq.x) + abs(dq.y) <= 1.) ? 1. : 0.;
                couleur += ((mod(fi, 2.) < .5) ? vec3(1., .85, .40) : vec3(1., .75, .90))*etoile*clamp(1.2 - vie, 0., 1.);
            }
        }
    }

    vec2 l = vec2(floor(P.x) - gHerosX, floor(P.y) - (SOL_Y + hy));
    if(abs(l.x) < 14. && l.y > -2. && l.y < 28.){
        vec4 hc = pixelHeros(l, fr, enAir, st, sp, clinHeros);
        if(hc.a > .5){
            couleur = hc.rgb*clamp(.55 + .6*lumiere, 0., 1.6);
        } else {
            float nb = pixelHeros(l + vec2(1., 0.), fr, enAir, st, sp, clinHeros).a
                     + pixelHeros(l - vec2(1., 0.), fr, enAir, st, sp, clinHeros).a
                     + pixelHeros(l + vec2(0., 1.), fr, enAir, st, sp, clinHeros).a
                     + pixelHeros(l - vec2(0., 1.), fr, enAir, st, sp, clinHeros).a;
            if(nb > .5) couleur = vec3(.05, .02, .10);
        }
    }

    couleur = dessinTuyau(P, wx, HEROS_X0, couleur, lumiere, t);
    if(niveauBoss < .5) couleur = dessinTuyau(P, wx, X_TUYAU, couleur, lumiere, t);

    if(st > 2.5 && st < 3.5 && sp > .3 && sp < .9){
        vec2 pv = P - vec2(gHerosX + 5.5, SOL_Y + hy + 7.5);
        float r = length(pv);
        float an = atan(pv.y, pv.x);
        float s2 = clamp((sp - .3)/.7, 0., 1.);
        float courant = mix(radians(115.), radians(-45.), smoothstep(0., 1., s2));
        float relatif = an - courant;
        if(r > 11. && r < 16. - 3.*relatif && relatif > 0. && relatif < 1.1){
            couleur += vec3(.9, .95, 1.) * (1. - relatif/1.1) * 1.3 * (1. - smoothstep(.75, .9, sp));
        }
    }

    if(niveauBoss > .5 && bMortDt > 0. && bMortDt < 2.4){
        vec2 ec = vec2(floor(BOSS_X - cameraX), SOL_Y + 22.);
        vec2 fp = floor(P);
        if(bMortDt < .1){
            vec2 dq = fp - ec;
            if((abs(dq.x) < 2. && abs(dq.y) < 26.) || (abs(dq.y) < 2. && abs(dq.x) < 26.) || length(dq) < 14.) couleur += vec3(1.);
        }
        float vie = max(bMortDt - .15, 0.);
        float fondu = clamp(1. - vie/2.1, 0., 1.);
        for(int i=0; i<8; i++){
            float fi = float(i);
            float angle = fi*.785 + hachage11(fi*2.3)*.3;
            vec2 position = ec + vec2(cos(angle), sin(angle))*(40. + 40.*hachage11(fi*1.3))*vie + vec2(0., 14.*vie - 30.*vie*vie);
            vec2 dq = fp - floor(position);
            float etoile = (abs(dq.x) + abs(dq.y) <= 1.) ? 1. : 0.;
            vec3 couleurEtoile3 = (mod(fi, 2.) < .5) ? vec3(.80, .55, 1.) : vec3(1., .95, .70);
            couleur += couleurEtoile3*etoile*fondu*(.6 + .4*sin(t*20. + fi));
        }
        vec2 hp = ec + vec2(sin(vie*6.)*3., 10. + 30.*vie);
        vec2 hq = floor((fp - floor(hp))/2.);
        couleur += vec3(1., .45, .65)*masqueCoeur(hq)*clamp(1.6 - vie, 0., 1.);
    }

    if(niveauBoss > .5 && tl > tK){
        vec2 fp = floor(P);
        for(int i=0; i<10; i++){
            float fi = float(i);
            float vie = tl - (tK + fi*.3);
            if(vie > 0. && vie < 4.2){
                float amplitude = 6. + 5.*mod(fi, 3.);
                vec2 position = vec2(centre.x + sin(vie*2. + fi*1.9)*amplitude + (hachage11(fi*3.1) - .5)*40.*vie/4.2, centre.y + 6.*hachage11(fi*1.9) + 20.*vie);
                vec2 hq = fp - floor(position);
                if(mod(fi, 3.) < .5) hq = floor(hq/2.);
                float fd = clamp((4.2 - vie)*2., 0., 1.)*clamp(vie*6., 0., 1.);
                vec3 couleurCoeur = mix(vec3(1., .35, .55), vec3(1., .72, .82), mod(fi, 2.));
                couleur = mix(couleur, couleurCoeur, masqueCoeur(hq)*fd);
            }
        }
    }

    float visibilite = clamp((hy + 23. - HAUT_TUYAU)/6. + 1., 0., 1.);
    vec2 dc = P - vec2(gHerosX, SOL_Y + hy + 16.);
    couleur += vec3(1., .80, .90) * .22*visibilite/(1. + dot(dc, dc)/90.);

    float rr = 999.;
    float tArrivee = T_ARRIVEE;
    vec2 ic = vec2(gHerosX, SOL_Y + HAUT_TUYAU);
    if(tl < 1.1) rr = 260.*smoothstep(0., 1., tl/1.1);
    else if(niveauBoss < .5 && tl > tArrivee + 1.0) rr = 260.*(1. - smoothstep(0., 1., (tl - tArrivee - 1.0)/.8));
    else if(niveauBoss > .5 && tl > DUREE_BOSS - 1.6){
        rr = 260.*(1. - smoothstep(0., 1., (tl - (DUREE_BOSS - 1.6))/.8));
        ic = centre;
    }
    if(length(P - ic) > rr) couleur = vec3(0.);

    couleur += max(couleur - .85, 0.)*.35;
    vec2 uv = fragCoord/iResolution.xy - .5;
    vec2 vv = uv*vec2(.9, 1.2);
    couleur *= 1. - .7*dot(vv, vv);
    couleur += (hachage21(P) - .5)/36.;
    couleur = floor(couleur*40. + .5)/40.;
    couleur = pow(max(couleur, 0.), vec3(.9));

    fragColor = vec4(couleur, 1.);
}

#define VITESSE 52.
#define HEROS_X0 88.
#define DUREE_SAUT .9
#define SEG_MAX 4.
#define SEGMENT 130.
#define T_DEPART 1.3
#define X_TUYAU ((SEG_MAX + 1.)*SEGMENT + 64.)
#define T_ARRIVEE (T_DEPART + (X_TUYAU - HEROS_X0)/VITESSE)
#define DUREE_NIV (T_ARRIVEE + 1.9)
#define X_STOP 320.
#define T_BOSS (T_DEPART + (X_STOP - HEROS_X0)/VITESSE)
#define DUREE_BOSS (T_BOSS + 17.5)
#define CYCLE (4.*DUREE_NIV + DUREE_BOSS)
#define PI 3.14159265
#define TAU 6.28318531

float gB, gBp;

float hachage11(float p){ p = fract(p*.1031); p *= p+33.33; p *= p+p; return fract(p); }
float freq(float s){ return 261.6256*exp2(s/12.); }
float env(float x, float k){ return (x < 0.) ? 0. : exp(-k*x); }
float sinus(float f, float x){ return sin(TAU*f*x); }
float tri(float f, float x){ return asin(clamp(sin(TAU*f*x), -1., 1.))*.6366; }
float carre(float f, float x){ float a = TAU*f*x; return (sin(a) + sin(3.*a)/3. + sin(5.*a)/5.)*.8; }
float cloche(float f, float x, float k)
{
    if(x < 0.) return 0.;
    return sin(TAU*f*x + 2.2*exp(-7.*x)*sin(TAU*f*3.5*x))*exp(-k*x);
}
float scie(float f, float x)
{
    float s = 0.;
    for(int h=1; h<=5; h++){
        float fh = float(h);
        s += sin(TAU*f*fh*x)/fh;
    }
    return s*.55;
}
float grosseCaisse(float x)
{
    if(x < 0.) return 0.;
    return sin(TAU*(52.*x + 90.*(1. - exp(-26.*x))/26.))*exp(-6.5*x);
}
float caisseClaire(float x)
{
    if(x < 0.) return 0.;
    return gB*.7*exp(-16.*x) + sin(TAU*185.*x)*.5*exp(-22.*x);
}
float charley(float x)
{
    if(x < 0.) return 0.;
    return (gB - gBp)*exp(-70.*x);
}
float penta(float k)
{
    k = mod(k, 5.);
    return (k < .5) ? 0. : ((k < 1.5) ? 2. : ((k < 2.5) ? 4. : ((k < 3.5) ? 7. : 9.)));
}
float arpNote(float k, float tierce)
{
    k = mod(k, 8.);
    return (k < .5) ? 0. : ((k < 1.5) ? tierce : ((k < 2.5) ? 7. : ((k < 3.5) ? 12. : ((k < 4.5) ? tierce + 12. : ((k < 5.5) ? 12. : ((k < 6.5) ? 7. : tierce))))));
}

float accord(float niv, float m, out float tierce)
{
    float i = mod(m, 4.);
    float r = 0.;
    tierce = 3.;
    if(niv < .5){
        r = (i < .5) ? 0. : ((i < 1.5) ? 8. : ((i < 2.5) ? 3. : 10.));
        tierce = (i < .5) ? 3. : 4.;
    } else if(niv < 1.5){
        r = (i < .5) ? 0. : ((i < 1.5) ? 10. : ((i < 2.5) ? 8. : 7.));
        tierce = (i < .5) ? 3. : 4.;
    } else if(niv < 2.5){
        r = (i < .5) ? 0. : ((i < 1.5) ? 2. : ((i < 2.5) ? 9. : 7.));
        tierce = (i > 1.5 && i < 2.5) ? 3. : 4.;
    } else if(niv < 3.5){
        r = (i < .5) ? 0. : ((i < 1.5) ? 7. : ((i < 2.5) ? 9. : 5.));
        tierce = (i > 1.5 && i < 2.5) ? 3. : 4.;
    } else if(niv < 4.5){
        r = (i < .5) ? 0. : ((i < 1.5) ? 8. : ((i < 2.5) ? 10. : 7.));
        tierce = (i < .5) ? 3. : 4.;
    } else {
        r = (i < .5) ? 0. : ((i < 1.5) ? 9. : ((i < 2.5) ? 5. : 7.));
        tierce = (i > .5 && i < 1.5) ? 3. : 4.;
    }
    return r;
}

vec2 pn(float v, float p)
{
    return v*vec2(1. - .6*p, 1. + .6*p);
}

void voie(inout vec2 d, inout vec2 w, float v, float gd, float gw, float p)
{
    vec2 q = pn(v, p);
    d += q*gd;
    w += q*gw;
}

float tempoNiv(float niv)
{
    float bpm = 96.;
    if(niv > .5) bpm = 132.;
    if(niv > 1.5) bpm = 84.;
    if(niv > 2.5) bpm = 124.;
    if(niv > 3.5) bpm = 150.;
    if(niv > 4.5) bpm = 72.;
    return bpm;
}

vec4 musique(float niv, float tl)
{
    float bpm = tempoNiv(niv);
    float cle = 2.;
    if(niv > .5) cle = 4.;
    if(niv > 1.5) cle = 7.;
    if(niv > 2.5) cle = 0.;
    if(niv > 3.5) cle = 9.;
    if(niv > 4.5) cle = 0.;
    float b = 60./bpm;
    float tb = tl/b;
    float beat = floor(tb);
    float xb = fract(tb)*b;
    float s8 = floor(tb*2.);
    float x8 = fract(tb*2.)*b*.5;
    float s16 = floor(tb*4.);
    float x16 = fract(tb*4.)*b*.25;
    float mesure = floor(tb/4.);
    float tierce;
    float rac = cle + accord(niv, mesure, tierce);
    float xm = mod(tb, 4.)*b;
    float padEnv = smoothstep(0., .6, xm)*(1. - smoothstep(4.*b - .5, 4.*b, xm));
    float pump = 1.;
    float imp = step(.5, mod(beat, 2.));
    float pair = 1. - imp;
    vec2 d = vec2(0.);
    vec2 w = vec2(0.);

    if(niv < .5){
        float pad = sin(TAU*freq(rac)*tl) + .8*sin(TAU*freq(rac + tierce)*tl + 1.) + .7*sin(TAU*freq(rac + 7.)*tl + 2.) + .5*sin(TAU*freq(rac + 12.)*tl);
        voie(d, w, pad*padEnv*.07*(.7 + .3*sin(tl*.9)), 1., 1., 0.);
        float bn = sinus(freq(rac - 24.), xb)*env(xb, 2.5)*(1. - exp(-60.*xb));
        voie(d, w, bn*.5*pair, 1., 0., 0.);
        float bl = cloche(freq(rac + 12. + arpNote(s8, tierce)), x8, 3.2);
        voie(d, w, bl*.26, .35, 1., sin(s8*1.7));
        voie(d, w, grosseCaisse(xb)*.4*step(mod(beat, 4.), .5), 1., 0., 0.);
        voie(d, w, charley(xb - b*.5)*.1, 1., 0., .3);
    } else if(niv < 1.5){
        pump = 1. - .45*exp(-9.*xb);
        float k8 = mod(s8, 8.);
        float oc = (k8 == 2. || k8 == 6.) ? 12. : ((k8 == 7.) ? 7. : 0.);
        float bs = scie(freq(rac - 24. + oc), x8)*env(x8, 5.);
        voie(d, w, bs*pump*.4, 1., 0., -.1);
        voie(d, w, grosseCaisse(xb)*.8, 1., 0., 0.);
        voie(d, w, caisseClaire(xb)*.55*imp, 1., .25, .05);
        voie(d, w, charley(x16)*.16*(.6 + .4*mod(s16, 2.)), 1., 0., .3);
        float ld = tanh(carre(freq(rac + 12. + arpNote(s16, tierce)), x16)*1.6)*env(x16, 9.);
        voie(d, w, ld*pump*.13, 1., 1.2, sin(s16)*.5);
        float pad = sin(TAU*freq(rac - 12.)*tl) + .7*sin(TAU*freq(rac - 12. + tierce)*tl) + .6*sin(TAU*freq(rac - 5.)*tl);
        voie(d, w, pad*padEnv*pump*.07, 1., .5, 0.);
    } else if(niv < 2.5){
        float g1 = cloche(freq(rac + 24. + arpNote(s8, tierce)), x8, 4.5);
        voie(d, w, g1*.14, .5, 1.6, sin(s8*2.3)*.7);
        float pd = 0.;
        for(int i=0; i<4; i++){
            float tn = (i == 0) ? 0. : ((i == 1) ? tierce : ((i == 2) ? 7. : 14.));
            float f = freq(rac + tn);
            pd += sin(TAU*f*1.002*tl + float(i)) + sin(TAU*f*.998*tl);
        }
        voie(d, w, pd*padEnv*.05*(.6 + .4*sin(tl*.7)), 1., 1., 0.);
        voie(d, w, sinus(freq(rac - 24.), xb)*env(xb, 1.8)*.45*pair, 1., 0., 0.);
        voie(d, w, grosseCaisse(xb)*.3*pair, 1., 0., 0.);
        voie(d, w, charley(x8)*.07, 1., 0., .4);
    } else if(niv < 3.5){
        float on = mod(s8, 2.);
        float bn = tri(freq(rac - 24. + 12.*on), x8)*env(x8, 6.);
        voie(d, w, bn*.5, 1., 0., 0.);
        float ms = mod(s8, 32.);
        float hh = hachage11(ms*1.9 + .5)*5.;
        float ml = carre(freq(cle + 12. + penta(floor(hh))), x8)*env(x8, 4.5)*step(.25, hachage11(ms*3.3 + .2));
        voie(d, w, ml*.18, 1., 1.1, sin(ms*1.3)*.4);
        voie(d, w, grosseCaisse(xb)*.5*pair, 1., 0., 0.);
        voie(d, w, caisseClaire(xb)*.35*imp, 1., .2, 0.);
        voie(d, w, charley(x8)*.09, 1., 0., .3);
        float pad = sin(TAU*freq(rac)*tl) + .8*sin(TAU*freq(rac + tierce)*tl) + .7*sin(TAU*freq(rac + 7.)*tl);
        voie(d, w, pad*padEnv*.04, 1., 1., 0.);
    } else if(niv < 4.5){
        pump = 1. - .4*exp(-9.*xb);
        float lo = (mod(s16, 4.) == 3.) ? 12. : 0.;
        float bs = scie(freq(rac - 24. + lo), x16)*env(x16, 6.);
        voie(d, w, bs*pump*.4, 1., 0., -.1);
        float m4 = mod(tb, 4.);
        float xs = ((m4 < 1.5) ? m4 : ((m4 < 2.5) ? m4 - 1.5 : ((m4 < 3.) ? m4 - 2.5 : m4 - 3.)))*b;
        float st = (scie(freq(rac + 12.), xs) + scie(freq(rac + 12. + tierce), xs) + scie(freq(rac + 19.), xs))*env(xs, 4.5);
        voie(d, w, st*pump*.12, 1., .5, 0.);
        voie(d, w, grosseCaisse(xb)*.85, 1., 0., 0.);
        voie(d, w, caisseClaire(xb)*.6*imp, 1., .3, .05);
        voie(d, w, charley(x16)*.14, 1., 0., .3);
        float xcr = mod(tb, 16.)*b;
        voie(d, w, (gB - gBp)*exp(-3.5*xcr)*.2, 1., .3, 0.);
        float ld = carre(freq(rac + 24. + arpNote(s16, tierce)), x16)*env(x16, 12.)*step(.5, mod(mesure, 2.));
        voie(d, w, ld*.09, 1., 1.3, sin(s16*.9)*.6);
    } else {
        float pd = 0.;
        for(int i=0; i<4; i++){
            float tn = (i == 0) ? 0. : ((i == 1) ? tierce : ((i == 2) ? 7. : 12.));
            float f = freq(rac + tn);
            float vib = 1. + .003*sin(tl*5.5 + float(i));
            pd += sin(TAU*f*1.003*vib*tl + float(i)) + sin(TAU*f*.997*vib*tl);
        }
        voie(d, w, pd*padEnv*.06, 1., 1., 0.);
        float bx2 = cloche(freq(rac + 24. + arpNote(s8, tierce)), x8, 5.5);
        voie(d, w, bx2*.24, .6, 1.2, sin(s8*1.9)*.6);
        float x2 = mod(tb, 2.)*b;
        voie(d, w, sinus(freq(rac - 24.), x2)*env(x2, 1.5)*.4, 1., 0., 0.);
    }
    return vec4(d, w);
}

vec4 piste(float lvl, float tl)
{
    float niv = lvl;
    float tm = tl;
    float g = smoothstep(0., 1.2, tl)*(1. - smoothstep(T_ARRIVEE + .9, T_ARRIVEE + 1.8, tl));
    if(lvl > 3.5){
        float tD = T_BOSS + 7.4;
        float tR = T_BOSS + 8.3;
        if(tl >= tD && tl < tR) return vec4(0.);
        if(tl < tD){
            niv = 4.;
            g = smoothstep(1.3, 2.5, tl)*(.6 + .4*smoothstep(T_BOSS - .3, T_BOSS + .2, tl))*(1. - smoothstep(tD - .08, tD, tl));
        } else {
            niv = 5.;
            tm = tl - tR;
            g = smoothstep(0., 2., tm)*(1. - smoothstep(DUREE_BOSS - 2.2, DUREE_BOSS - .6, tl));
        }
    }
    if(tm < 0.) return vec4(0.);
    return musique(niv, tm)*g;
}

void ajoute(inout vec2 s, float v, float p)
{
    s += pn(v, p);
}

float fxSaut(float x)
{
    if(x < 0. || x > .4) return 0.;
    return sin(TAU*(260.*x + 700.*x*x))*exp(-7.*x)*.35;
}

float fxPose(float x)
{
    if(x < 0. || x > .3) return 0.;
    return (sin(TAU*(110.*x - 120.*x*x))*.5 + gB*.25)*exp(-24.*x)*.35;
}

float fxBoing(float x)
{
    if(x < 0. || x > .6) return 0.;
    return sin(TAU*(420.*x + 14.*sin(38.*x)))*exp(-7.*x)*.38 + gB*.2*exp(-80.*x);
}

float fxShing(float x)
{
    if(x < 0. || x > .4) return 0.;
    return cloche(2200., x, 9.)*.18 + (gB - gBp)*.12*exp(-14.*x);
}

float fxSwish(float x)
{
    if(x < 0. || x > .3) return 0.;
    float e = sin(PI*x/.3);
    return (gB - gBp + gB*.3)*e*e*.3;
}

float fxClic(float x)
{
    if(x < 0. || x > .1) return 0.;
    return sin(TAU*1800.*x)*exp(-90.*x)*.15;
}

float fxPouf(float x)
{
    if(x < 0. || x > .9) return 0.;
    float s = 0.;
    if(x < .25) s += sin(TAU*(700.*x - 1500.*x*x))*exp(-16.*x)*.4;
    s += gB*exp(-30.*x)*.25;
    s += cloche(1568., x - .04, 7.)*.12 + cloche(1976., x - .1, 7.)*.12 + cloche(2349., x - .16, 7.)*.12;
    return s;
}

float fxRugit(float x)
{
    if(x < 0. || x > .8) return 0.;
    return (scie(85. + 12.*sin(TAU*9.*x), x)*.5 + gB*.3)*sin(PI*x/.8)*.5;
}

float fxCri(float x)
{
    if(x < 0. || x > .4) return 0.;
    return sin(TAU*(900.*x - 1100.*x*x))*exp(-9.*x)*.3;
}

float fxChoc(float x)
{
    if(x < 0. || x > 1.2) return 0.;
    return grosseCaisse(x)*.9 + sinus(38., x)*exp(-5.*x)*.5 + gB*exp(-14.*x)*.4;
}

float fxOnde(float x)
{
    if(x < 0. || x > 1.8) return 0.;
    return (gB + gBp)*.5*(.5 + .5*sin(TAU*14.*x))*exp(-1.3*x)*.35;
}

float fxExplosion(float x)
{
    if(x < 0. || x > 2.) return 0.;
    return sinus(60., x)*exp(-3.*x)*.7 + gB*exp(-6.*x)*.6 + (gB - gBp)*exp(-2.5*x)*.35;
}

float fxScintille(float x)
{
    if(x < 0. || x > 1.5) return 0.;
    float s = 0.;
    for(int i=0; i<6; i++){
        float fi = float(i);
        s += cloche(1568.*exp2(penta(fi)/12.), x - fi*.06, 6.)*.1;
    }
    return s;
}

float fxBaiser(float x)
{
    if(x < 0. || x > .25) return 0.;
    float e = sin(PI*x/.25);
    return sin(TAU*(750.*x - 1200.*x*x))*e*.22 + gB*.05*e;
}

vec2 effets(float lvl, float tl, float tc)
{
    vec2 s = vec2(0.);
    float air = 0.;
    float run = 0.;
    if(tl < 1.) ajoute(s, sin(TAU*(180.*tl + 260.*tl*tl))*sin(PI*tl)*.3, 0.);
    if(lvl < 3.5){
        run = (tl > T_DEPART && tl < T_ARRIVEE - DUREE_SAUT) ? 1. : 0.;
        for(int i=1; i<=4; i++){
            float sid = float(i);
            float sh = sid + lvl*97.;
            float r = hachage11(sh*7.31 + 1.7);
            float xc = floor(sid*SEGMENT + 62. + 28.*hachage11(sh*3.9 + 5.));
            float tp = 0.;
            if(r >= .08) tp = 1.;
            if(r >= .26) tp = 2.;
            if(r >= .44) tp = 3.;
            if(r >= .56) tp = 4.;
            if(r >= .72) tp = 5.;
            if(r >= .88) tp = 6.;
            float tx = T_DEPART + (xc - HEROS_X0)/VITESSE;
            if(tp > .5 && tp < 3.5){
                float tj = tx - DUREE_SAUT*.5;
                ajoute(s, fxSaut(tl - tj), 0.);
                ajoute(s, fxPose(tl - tj - DUREE_SAUT), 0.);
                if(tl > tj && tl < tj + DUREE_SAUT) air = 1.;
            }
            if(tp > 4.5 && tp < 5.5){
                float tj2 = tx - 24./VITESSE;
                ajoute(s, fxSaut(tl - tj2), 0.);
                ajoute(s, fxBoing(tl - tx) + fxPouf(tl - tx)*.8, .5);
                ajoute(s, fxPose(tl - tx - .5)*.7, 0.);
                if(tl > tj2 && tl < tx + .5) air = 1.;
            }
            if((tp > 3.5 && tp < 4.5) || tp > 5.5){
                float th = tx - 20./VITESSE;
                ajoute(s, fxShing(tl - th + .7), 0.);
                ajoute(s, fxClic(tl - th + .35), 0.);
                ajoute(s, fxSwish(tl - th + .15), 0.);
                ajoute(s, fxPouf(tl - th), .5);
                ajoute(s, fxShing(tl - th - .45)*.5, 0.);
            }
        }
        float ta = T_ARRIVEE;
        ajoute(s, fxSaut(tl - ta + DUREE_SAUT), 0.);
        ajoute(s, fxPose(tl - ta)*1.2, 0.);
        float xw = tl - ta - .5;
        if(xw > 0. && xw < .9) ajoute(s, sin(TAU*(700.*xw - 560.*xw*xw))*sin(PI*xw/.9)*.3, 0.);
        if(tl > ta - DUREE_SAUT && tl < ta) air = 1.;
    } else {
        float T0 = T_BOSS;
        float tF = T0 + 6.;
        float tR = T0 + 8.5;
        float tD = T0 + 7.4;
        float tK = T0 + 10.4;
        run = ((tl > T_DEPART && tl < T0) || (tl > tF && tl < tF + .9) || (tl > tR && tl < tR + 1.6)) ? 1. : 0.;
        ajoute(s, fxRugit(tl - T0), .55);
        for(int i=0; i<2; i++){
            float ts = T0 + .8 + 3.6*float(i);
            ajoute(s, fxSaut(tl - ts), 0.);
            float xh = tl - ts - .9;
            ajoute(s, fxChoc(xh)*.6 + fxBoing(xh), .55);
            ajoute(s, fxCri(xh - .03), .6);
            ajoute(s, fxSaut(xh)*.7, 0.);
        }
        float tL = T0 + 3.2;
        ajoute(s, fxSaut(tl - (T0 + 2.6))*.8, .6);
        ajoute(s, fxChoc(tl - tL), .55);
        ajoute(s, fxOnde(tl - tL), .6 - 1.6*clamp((tl - tL)/1.8, 0., 1.));
        ajoute(s, fxSaut(tl - (T0 + 3.41)), 0.);
        ajoute(s, fxPose(tl - (T0 + 4.31)), 0.);
        ajoute(s, fxShing(tl - tD + .7), 0.);
        ajoute(s, fxClic(tl - tD + .35), 0.);
        ajoute(s, fxSwish(tl - tD + .15), 0.);
        ajoute(s, fxExplosion(tl - tD), .5);
        ajoute(s, fxPouf(tl - tD), .5);
        ajoute(s, fxScintille(tl - tD - .15), .8);
        ajoute(s, fxShing(tl - tD - .45)*.5, 0.);
        float kt = (tl - tK)/.35;
        ajoute(s, fxBaiser(tl - tK), .4);
        ajoute(s, fxPose(tl - tK - .35)*.5, 0.);
        ajoute(s, fxPose(tl - tK - .7)*.5, 0.);
        for(int i=0; i<10; i++){
            float fi = float(i);
            ajoute(s, cloche(freq(48. + penta(fi) + 12.*floor(fi/5.)), tl - (tK + fi*.3), 4.)*.12, sin(fi*2.1)*.6);
        }
        if((tl > T0 + .8 && tl < T0 + 1.7) || (tl > T0 + 4.4 && tl < T0 + 5.3) || (tl > T0 + 2.6 && tl < T0 + 3.2) || (tl > T0 + 3.41 && tl < T0 + 4.31) || (kt > 0. && kt < 2.)) air = 1.;
    }
    float xs = mod(tc - .1, .2);
    ajoute(s, (gB*.5*exp(-60.*xs) + sin(TAU*95.*xs)*exp(-35.*xs))*.14*run*(1. - air), 0.);
    return s;
}

vec2 mainSound(int samp, float time)
{
    float t = mod(time, CYCLE);
    float lvl = (t < 4.*DUREE_NIV) ? floor(t/DUREE_NIV) : 4.;
    float tl = t - lvl*DUREE_NIV;
    float sn = float(samp);
    gB = hachage11(mod(sn, 65521.))*2. - 1.;
    gBp = hachage11(mod(sn - 1., 65521.))*2. - 1.;
    float d1 = .75*60./tempoNiv((lvl > 3.5 && tl > T_BOSS + 8.3) ? 5. : lvl);
    vec4 m0 = piste(lvl, tl);
    vec4 m1 = piste(lvl, tl - d1);
    vec4 m2 = piste(lvl, tl - 2.*d1);
    vec2 mus = m0.xy + m0.zw*.35 + vec2((m2.z + m2.w)*.5, (m1.z + m1.w)*.5)*.35;
    vec2 fx = effets(lvl, tl, t);
    vec2 o = mus*.8 + fx;
    o = tanh(o*1.1)*.9;
    return o;
}
